const i=e=>{const t=new Map(e.s.nodes.map(a=>[a.id,a]));let o=0;for(const a of e.s.members){if(a.kind==="tie"||!a.sec)continue;const n=t.get(a.n1),s=t.get(a.n2);n&&s&&(o+=a.sec.b*a.sec.h*Math.hypot(s.x-n.x,s.y-n.y))}return o},r=e=>e.sol.ok?Math.max(0,...e.sol.members.filter(t=>t.id.startsWith("G")).map(t=>t.maxM.value)):0,m=e=>e.sol.ok?Math.max(0,...e.sol.members.map(t=>Math.max(Math.abs(t.maxM.value),Math.abs(t.minM.value)))):0,h=[{id:"l.rc-sys-misc.weak",xp:30,title:{en:"Make the soil weak, bring the span down to 16 m or less and choose the frame that stays determinate",ar:"خلّي التربة ضعيفة، ونزّل البحر لـ 16 م أو أقل، واختار الإطار اللي بيفضل محدد"},hint:{en:"A three-hinged frame is used up to 16 m; beyond it a tied system takes over.",ar:"الإطار ثلاثي المفصلات بيستخدم لحد 16 م؛ وبعدها نظام بشداد بياخد مكانه."},check:e=>e.template==="studio"&&e.params.soil==="weak"&&e.params.sys==="3h"&&Number(e.params.L)<=16&&e.sol.ok},{id:"l.rc-sys-misc.light",xp:40,title:{en:"At 30 m or more, find a system with less than 20 m³ of concrete",ar:"عند 30 م أو أكتر، لاقي نظام خرسانته أقل من 20 م³"},hint:{en:"Put the thrust in a tie and the members on the thrust line.",ar:"حط الدفع في شداد والأعضاء على خط الضغط."},check:e=>e.template==="studio"&&Number(e.params.L)>=30&&e.sol.ok&&i(e)<20}],l=[{id:"l.rc-sys-misc.align",xp:30,title:{en:"Lean the posts along the springing force: the bending disappears",ar:"ميّل الأعمدة مع قوة الارتكاز: العزوم بتختفي"},check:e=>e.template==="archslab"&&e.params.sup==="posts"&&e.params.load==="full"&&e.sol.ok&&m(e)<.5}],$=[{id:"l.rc-sys-misc.haunch",xp:30,title:{en:"Haunch the knees until the mid-span moment is below 30% of wL²/8",ar:"اعمل فيونكات للأركان لحد ما عزم نص البحر ينزل تحت 30% من wL²/8"},check:e=>e.template==="haunchframe"&&e.params.haunch==="haunch"&&r(e)>0&&r(e)<.3*Number(e.params.w)*Number(e.params.L)**2/8},{id:"l.rc-sys-misc.deeper",xp:30,title:{en:"Make the knees twice as deep as the beam and read the headroom gained",ar:"خلّي الأركان ضعف عمق الكمرة واقرا الارتفاع الصافي المكسوب"},check:e=>e.template==="haunchframe"&&e.params.haunch==="haunch"&&Number(e.params.k)>=2-1e-9&&e.tab==="hand"}],d={sections:[{id:"read",title:{en:"Reading an exam elevation",ar:"قراية واجهة الامتحان"},blocks:[{t:"p",text:{en:"A systems problem gives an **elevation** (sometimes a plan): spans that must stay free of columns, levels such as +7.00 and +4.00, sky-lights, the use of the hall and the soil. The system is chosen **from that elevation** — from where supports are allowed and what must pass under the roof — not from the outline of the slab on the plan. Work in this order:",ar:"مسألة الأنظمة بتدّيك **واجهة** (وساعات مسقط): بحور لازم تفضل من غير أعمدة، ومناسيب زي +7.00 و +4.00، وشخشيخة، واستخدام الصالة، والتربة. النظام بيتختار **من الواجهة دي** — من الأماكن اللي مسموح فيها بركائز واللي لازم يعدّي تحت السقف — مش من شكل البلاطة في المسقط. اشتغل بالترتيب ده:"}},{t:"steps",items:[{en:"Mark the spans that must be column-free and the levels; the main system runs in the **short direction**.",ar:"علّم البحور اللي لازم تبقى من غير أعمدة والمناسيب؛ والنظام الرئيسي بيمشي في **الاتجاه القصير**."},{en:"Put each span in the **range** of the systems (the matrix below).",ar:"حط كل بحر في **مدى** الأنظمة (الجدول اللي تحت)."},{en:"**Soil**: weak → determinate or roller–hinged systems; rock → fixed frames are welcome.",ar:"**التربة**: ضعيفة ← أنظمة محددة أو مفصلية–متحركة؛ وصخر ← الإطارات الثابتة مرحّب بيها."},{en:"**Light, use, architecture**: north light → saw-tooth; a round plan → radial frames or a dome; floors above a free space → a transfer frame up to 24 m, a storey-deep Vierendeel beyond; an overhang → a cantilever frame; a curved roof → an arch slab or an arch girder.",ar:"**الإضاءة والاستخدام والمعماري**: إضاءة شمالية ← منشاري؛ مسقط دائري ← إطارات شعاعية أو قبة؛ أدوار فوق فراغ حر ← إطار تحويل لحد 24 م، وفيرندل بعمق دور بعد كده؛ كابولي كبير ← إطار كابولي؛ سقف منحني ← بلاطة مقوّسة أو كمرة مقوّسة."},{en:"Size it by its rules, then follow the forces down: thrusts and moments into columns and footings, and the wind across the systems into the end gables.",ar:"حط أبعاده بقواعده، وبعدين امشي ورا القوى لتحت: الدفع والعزوم للأعمدة والقواعد، والرياح العمودية على الأنظمة للواجهات الطرفية."}]},{t:"p",text:{en:"**How an exam elevation is read.** The outline drawn is the outline of the **slab** — the shape of the roof, not necessarily the shape of the system under it — and the levels written on it (+7.00, +4.00…) are **slab levels**. A column line drawn down to the ground only shows where the column ends: it does not mean a fixed base — the base is your choice. At a step between two roof levels the vertical line is **one column** carrying both roofs, not two. A modest step of about 3 m needs no settlement joint; that joint is kept for differences of about 6–8 m on weak soil.",ar:"**إزاي بنقرا واجهة الامتحان.** الحدود المرسومة هي حدود **البلاطة** — شكل السقف، مش بالضرورة شكل النظام اللي تحته — والمناسيب المكتوبة عليها (+7.00 و +4.00…) هي **مناسيب البلاطات**. وخط العمود النازل لحد الأرض بيوضح بس العمود بينتهي فين: مش معناه ركيزة ثابتة — نوع الركيزة اختيارك. وعند الدرجة بين منسوبين للسقف الخط الرأسي ده **عمود واحد** شايل السقفين، مش عمودين. والدرجة العادية حوالي 3 م مش محتاجة فاصل هبوط؛ الفاصل ده بنسيبه لفروق حوالي 6–8 م على التربة الضعيفة."}},{t:"p",text:{en:"A complete answer shows: the statical sketch with its loads and supports; the B.M.D (and N.F.D) drawn on the tension side; an elevation with the concrete dimensions and the levels; the reinforcement in elevation with cross-sections — often with every bar drawn apart in a bar diagram; and the footings, drawn shifted wherever a column brings a moment.",ar:"الإجابة الكاملة بتوضح: الكروكي الإنشائي بأحماله وركائزه؛ ومنحنى العزوم (ومنحنى القوى العمودية) مرسوم ناحية الشد؛ وواجهة بالأبعاد الخرسانية والمناسيب؛ والتسليح في الواجهة مع قطاعات عرضية — وغالباً كل سيخ مرسوم لوحده في تفريد؛ والقواعد، مرسومة مترحّلة في أي مكان العمود جايب فيه عزم."}},{t:"quiz",q:{kind:"mcq",q:{en:"The statical system of an exam hall is chosen mainly from…",ar:"النظام الإنشائي لصالة الامتحان بيتختار أساساً من…"},options:[{en:"the elevation: free spans, levels and where supports are allowed",ar:"الواجهة: البحور الحرة والمناسيب وأماكن الركائز المسموحة"},{en:"the outline of the slab on the plan",ar:"شكل البلاطة في المسقط"},{en:"the number of floors of the neighbours",ar:"عدد أدوار الجيران"}],answer:0,explain:{en:"The plan outline says little about what must span; the elevation shows it.",ar:"شكل المسقط مش بيقول كتير عن اللي لازم يتغطى؛ والواجهة هي اللي بتوضحه."}}}]},{id:"matrix",title:{en:"All the systems at a glance",ar:"كل الأنظمة في نظرة"},blocks:[{t:"table",head:[{en:"System",ar:"النظام"},{en:"Span",ar:"البحر"},{en:"Depth",ar:"العمق"},{en:"The thrust goes…",ar:"الدفع بيروح…"},{en:"Soil",ar:"التربة"}],rows:[[{en:"girder: simple / continuous / cantilever",ar:"كمرة: بسيطة / مستمرة / كابولي"},"4–12 m","L/10, L/12, Lc/5",{en:"nowhere",ar:"مفيش"},{en:"simple: any",ar:"البسيطة: أي تربة"}],[{en:"girder on neoprene bearings",ar:"كمرة على ركائز نيوبرين"},"12–40 m","L/10",{en:"nowhere",ar:"مفيش"},{en:"any",ar:"أي تربة"}],[{en:"cantilever frame (strut / tie)",ar:"إطار كابولي (دعامة / شداد)"},"2–6 (6–10) m","Lc/5; L/(7–8)",{en:"all the moment into one column",ar:"العزم كله في عمود واحد"},{en:"medium / hard",ar:"متوسطة / قوية"}],[{en:"three-hinged frame",ar:"إطار ثلاثي المفصلات"},"12–16 m","L/10",{en:"X into the footings",ar:"X للقواعد"},{en:"weak",ar:"ضعيفة"}],[{en:"two-hinged frame",ar:"إطار ذو مفصلين"},"12–22 m","L/(12–14)",{en:"X, no moment",ar:"X من غير عزم"},{en:"sand / no data",ar:"رمل / مفيش بيانات"}],[{en:"fixed-base frame",ar:"إطار ثابت الركائز"},"12–24 m","L/(14–16)",{en:"X and a moment",ar:"X وعزم"},{en:"hard / rock",ar:"قوية / صخر"}],[{en:"heavy frame",ar:"إطار حامل"},"12–24 m","L/(8–10)",{en:"large X and moments",ar:"X كبيرة وعزوم"},{en:"fixed; two-hinged if weak",ar:"ثابت؛ مفصلين لو ضعيفة"}],[{en:"saw-tooth: slab / girder type",ar:"منشاري: بلاطة / كمرة"},"4–8; 8–15 m","L'/(30–35); L/(12–14)",{en:"X·S on edge columns unless tied",ar:"X·S على الأعمدة الطرفية لو مفيش شداد"},{en:"any",ar:"أي تربة"}],[{en:"polygon frame: triangle / trapezoid",ar:"إطار مضلع: مثلث / شبه منحرف"},"12–16; 12–24 m",{en:"rise L/(6–8), t L/(20–25)",ar:"الارتفاع L/(6–8)، و t من L/25 لـ L/20"},{en:"into the tie",ar:"في الشداد"},{en:"any",ar:"أي تربة"}],[{en:"arch girder",ar:"كمرة مقوّسة"},"24–40 m",{en:"rise L/(6–8), t L/(20–25)",ar:"الارتفاع L/(6–8)، و t من L/25 لـ L/20"},{en:"into the tie",ar:"في الشداد"},{en:"any",ar:"أي تربة"}],[{en:"radial frames (round halls)",ar:"إطارات شعاعية (صالات دائرية)"},"6–12 m",{en:"L/(6–8) at the knee",ar:"L/(6–8) عند الركن"},{en:"into the inner ring",ar:"في الحلقة الداخلية"},{en:"medium / hard",ar:"متوسطة / قوية"}],[{en:"arch slab",ar:"بلاطة مقوّسة"},"8–18 m",{en:"rise L/(6–8), 80–140 mm",ar:"الارتفاع L/(6–8)، و 80–140 مم"},{en:"X·S into ties",ar:"X·S في الشدادات"},{en:"any, with ties",ar:"أي تربة، بالشدادات"}],[{en:"RC truss",ar:"جمالون خرساني"},"15–40 m",{en:"h L/(6–8); L/40, L/50",ar:"h من L/8 لـ L/6؛ و L/40 و L/50"},{en:"nowhere",ar:"مفيش"},{en:"any",ar:"أي تربة"}],[{en:"Vierendeel girder",ar:"كمرة فيرندل"},"15–40 m",{en:"h L/(6–8), t L/20; storey, L/(10–12)",ar:"h من L/8 لـ L/6، و t = L/20؛ أو دور، و L/(10–12)"},{en:"nowhere",ar:"مفيش"},{en:"any",ar:"أي تربة"}],[{en:"dome / cone",ar:"قبة / مخروط"},"—",{en:"shell ≥ 80 mm (water 160)",ar:"القشرة ≥ 80 مم (المية 160)"},{en:"ring force H·r",ar:"قوة الحلقة H·r"},{en:"any",ar:"أي تربة"}],[{en:"end gables (wind across)",ar:"الواجهات الطرفية (الرياح العمودية)"},{en:"columns every 4–8 m",ar:"أعمدة كل 4–8 م"},"L₁/12",{en:"into the gable columns",ar:"في أعمدة الواجهة"},"—"]],caption:{en:'"Nowhere" = roller–hinged: the columns receive vertical loads (and wind) only.',ar:"«مفيش» = مفصلي–متحرك: الأعمدة بتاخد أحمال رأسية (ورياح) بس."}},{t:"quiz",q:{kind:"mcq",q:{en:"A 34 m column-free hall on medium soil. Which system is outside its usual range?",ar:"صالة 34 م من غير أعمدة على تربة متوسطة. أنهي نظام برّه مداه المعتاد؟"},options:[{en:"a two-hinged frame",ar:"إطار ذو مفصلين"},{en:"an arch girder",ar:"كمرة مقوّسة"},{en:"an RC truss",ar:"جمالون خرساني"}],answer:0,explain:{en:"Two-hinged frames stop at about 22 m; arch girders (24–40) and trusses (15–40) cover 34 m.",ar:"الإطارات ذات المفصلين بتقف عند حوالي 22 م؛ والكمرات المقوّسة (24–40) والجمالونات (15–40) بتغطي 34 م."}}}]},{id:"choice",title:{en:"Deciding between neighbouring systems",ar:"الاختيار بين الأنظمة المتقاربة"},blocks:[{t:"p",text:{en:"Where two systems share a span range, a few rules decide. **Weak soil, or a large temperature difference between the inside and the outside** of the hall (a cold store, an air-conditioned hall in a hot climate), calls for an **externally determinate** system: its supports pass no thrust and no moment to the footings, so neither a settling footing nor a roof that grows and shrinks can bend it. Each has its limit:",ar:"لما نظامين يشتركوا في نفس مدى البحر، شوية قواعد بتحسم. **التربة الضعيفة، أو فرق حرارة كبير بين جوه الصالة وبرّه** (ثلاجة تخزين، أو صالة متكيّفة في جو حر)، بيطلبوا نظام **محدد خارجياً**: ركائزه مابتنقلش دفع ولا عزم للقواعد، فلا القاعدة اللي بتهبط ولا السقف اللي بيتمدد ويتقلص يقدروا يحنوه. ولكل واحد حده:"}},{t:"table",head:[{en:"Externally determinate system",ar:"النظام المحدد خارجياً"},{en:"Span up to",ar:"البحر لحد"}],rows:[[{en:"simple girder",ar:"كمرة بسيطة"},"12 m"],[{en:"three-hinged frame",ar:"إطار ثلاثي المفصلات"},"16 m"],[{en:"polygon frame (hinge + roller, tied)",ar:"إطار مضلع (ركيزة مفصلية + متحركة، بشداد)"},"24 m"],[{en:"arch girder (hinge + roller, tied)",ar:"كمرة مقوّسة (ركيزة مفصلية + متحركة، بشداد)"},"40 m"],[{en:"RC truss",ar:"جمالون خرساني"},"40 m"]],caption:{en:"Weak soil or a large inside–outside temperature difference: choose from this list.",ar:"تربة ضعيفة أو فرق حرارة كبير بين جوه وبرّه: اختار من القايمة دي."}},{t:"steps",items:[{en:"**Beyond 12 m** a girder cast with its columns gives way to a frame (or to a girder on real bearings). Where the soil allows an indeterminate frame, the **two-hinged** one is preferred to the fixed one: a single redundant, the quickest to solve.",ar:"**بعد 12 م** الكمرة المصبوبة مع أعمدتها بتسيب مكانها للإطار (أو لكمرة على ركائز حقيقية). ولو التربة تسمح بإطار غير محدد، الإطار **ذو المفصلين** مفضّل عن الثابت: مجهول زائد واحد، وأسرع حل."},{en:"**12–24 m: frame or polygon frame?** A roof slab that bears directly on the main members — a two-way slab, or a one-way slab spanning from one main system to the next — needs a **frame**, whose straight beam takes a distributed load; a polygon frame wants its loads at its joints. **Weak soil** → the **polygon frame** (tied, on a hinge and a roller). A **sky-light** (شخشيخة) of height $h_s$ carried by the system: $h_s < L/(6 \\to 8)$ → an ordinary frame; $h_s \\ge L/(6 \\to 8)$ → a polygon frame, which has that rise anyway. On a **three-hinged** frame the sky-light is itself a small three-hinged frame: its posts are hinged on the main beam and its crown hinge stands right above the main one, so the system stays determinate. On a two-hinged or fixed frame the posts and the sky-light roof form a small rigid frame cast with the main beam; a two-hinged frame carrying a sky-light is kept to 12–20 m, since the open middle has no slab flange and takes the post loads.",ar:"**12–24 م: إطار ولا إطار مضلع؟** بلاطة سقف قاعدة مباشرة على الأعضاء الرئيسية — بلاطة في اتجاهين، أو بلاطة في اتجاه واحد بحرها من نظام رئيسي للي بعده — محتاجة **إطار**، كمرته المستقيمة بتاخد حمل موزع؛ والإطار المضلع عايز أحماله عند عقده. **تربة ضعيفة** ← **الإطار المضلع** (بشداد، على ركيزة مفصلية وركيزة متحركة). و**شخشيخة** ارتفاعها $h_s$ شايلها النظام: $h_s < L/(6 \\to 8)$ ← إطار عادي؛ و $h_s \\ge L/(6 \\to 8)$ ← إطار مضلع، لأنه أصلاً ليه الارتفاع ده. وعلى إطار **ثلاثي المفصلات** الشخشيخة نفسها بتبقى إطار صغير ثلاثي المفصلات: قوائمها متمفصلة على الكمرة الرئيسية ومفصلة تاجها واقفة فوق مفصلة التاج الرئيسية بالظبط، فالنظام بيفضل محدد. وعلى إطار ذو مفصلين أو ثابت الركائز، القوائم وسقف الشخشيخة بيعملوا إطار صغير جاسئ مصبوب مع الكمرة الرئيسية؛ والإطار ذو المفصلين اللي شايل شخشيخة بيتحدد بـ 12–20 م، لأن النص المفتوح مالوش شفة من البلاطة وبياخد أحمال القوائم."},{en:"**Beyond 24 m**: a roof on two supports → an **arch girder** (the first choice); a beam with a cantilever (say 28 m plus an 8 m overhang) → an RC **truss** with overhanging panels.",ar:"**بعد 24 م**: سقف على ركيزتين ← **كمرة مقوّسة** (أول اختيار)؛ وكمرة بكابولي (مثلاً 28 م وكابولي 8 م) ← **جمالون** خرساني ببواكي طالعة كابولي."},{en:"**A building over a free hall**: up to 24 m a transfer frame (600–800 mm wide, $t \\approx L/(7 \\to 8)$) carries the floors; beyond 24 m a storey-deep Vierendeel (the Vierendeel episode).",ar:"**مبنى فوق صالة حرة**: لحد 24 م إطار تحويل (عرضه 600–800 مم، و $t \\approx L/(7 \\to 8)$) بيشيل الأدوار؛ وبعد 24 م فيرندل بعمق دور (حلقة الفيرندل)."}]},{t:"p",text:{en:"**Example.** An 18 m hall frame must carry a central sky-light: $L/8 = 2.25$ m and $L/6 = 3.0$ m. A 1.6 m sky-light stands on an ordinary frame; a 3.2 m one is above the range — shape the system as a polygon frame and let its rise make the sky-light.",ar:"**مثال.** إطار صالة 18 م لازم يشيل شخشيخة في النص: $L/8 = 2.25$ م و $L/6 = 3.0$ م. شخشيخة 1.6 م بتقف على إطار عادي؛ وشخشيخة 3.2 م فوق المدى — شكّل النظام إطار مضلع وخلّي ارتفاعه هو اللي يعمل الشخشيخة."}},{t:"quiz",q:{kind:"mcq",q:{en:"A 20 m hall frame must carry a sky-light 3.5 m high. The better system is…",ar:"إطار صالة 20 م لازم يشيل شخشيخة ارتفاعها 3.5 م. النظام الأنسب…"},options:[{en:"a polygon frame, whose rise makes the sky-light",ar:"إطار مضلع، ارتفاعه هو اللي بيعمل الشخشيخة"},{en:"a two-hinged frame with the sky-light standing on its beam",ar:"إطار ذو مفصلين والشخشيخة واقفة على كمرته"},{en:"a simple girder",ar:"كمرة بسيطة"}],answer:0,explain:{en:"$L/(6 \\to 8) = 3.33 \\to 2.5$ m; 3.5 m is above it, so the polygon frame. A girder stops at 12 m.",ar:"$L/(6 \\to 8) = 3.33 \\to 2.5$ م؛ و 3.5 م فوقهم، يبقى الإطار المضلع. والكمرة بتقف عند 12 م."}}}]},{id:"soil",title:{en:"Soil, levels, joints and stability",ar:"التربة والمناسيب والفواصل والاستقرار"},blocks:[{t:"steps",items:[{en:"**Weak soil** (or a large temperature difference between inside and outside): determinate systems — three-hinged frames, girders with hinges near L/5, floating bays — or roller–hinged ones that bring no thrust (trusses, tied arches). **Rock**: systems indeterminate several times over, such as fixed frames, whose smaller moments are then safe.",ar:"**التربة الضعيفة** (أو فرق حرارة كبير بين جوه وبرّه): أنظمة محددة — إطارات ثلاثية المفصلات، وكمرات بمفصلات قريب من L/5، وبواكي عائمة — أو مفصلية–متحركة مابتجيبش دفع (جمالونات، وعقود بشدادات). **الصخر**: أنظمة غير محددة بدرجات عالية، زي الإطارات الثابتة، وعزومها الأصغر ساعتها في الأمان."},{en:"**Level differences** of about 6–8 m between two parts on weak soil: separate them by a **settlement joint** or hang one part as a floating bay. A step of about 3 m is not large: no joint.",ar:"**فرق مناسيب** حوالي 6–8 م بين جزئين على تربة ضعيفة: افصلهم بـ**فاصل هبوط** أو علّق جزء كباكية عائمة. ودرجة حوالي 3 م مش كبيرة: من غير فاصل."},{en:"**L- or T-shaped plans**: a **structural joint** cuts them into rectangles (no torsion) — along the **short direction**, the shortest line that does it: an L of a 40 × 18 m wing and an 18 × 16 m wing is cut along the 18 m line where they meet. If interior columns are allowed, put columns along the joint line under the frames that end there. If no interior column is allowed on that line, a **heavy frame** along the joint line carries the ends of the frames that land on it.",ar:"**المساقط على شكل L أو T**: **فاصل إنشائي** بيقسمها لمستطيلات (من غير التواء) — في **الاتجاه القصير**، أقصر خط يعمل كده: حرف L من جناح 40 × 18 م وجناح 18 × 16 م بيتقطع على خط الـ 18 م اللي بيتقابلوا عنده. ولو الأعمدة الداخلية مسموحة، حط أعمدة على خط الفاصل تحت الإطارات اللي بتنتهي عنده. ولو ممنوع أي عمود داخلي على الخط ده، **إطار حامل** على طول خط الفاصل بيشيل أطراف الإطارات اللي بتقع عليه."},{en:"**Stability**: a cantilever frame must be fixed to a stable base or system — hinged, it is a mechanism. Closed frames are avoided: highly indeterminate and awkward to solve by hand.",ar:"**الاستقرار**: الإطار الكابولي لازم يتثبت في قاعدة أو نظام مستقر — لو مفصلي يبقى ميكانيزم. والإطارات المقفولة بنتجنبها: غير محددة بدرجة عالية وصعب تتحل باليد."}]},{t:"p",text:{en:"The lab puts the same 24 m span and 60 kN/m on seven systems, each at its depth rule. The largest moments: two-hinged frame 2452 kN·m (26.6 m³ of concrete with its columns), fixed frame 2531 kN·m (23.0 m³), tied arch girder 77 kN·m (11.1 m³), truss 61 kN·m (22.6 m³), Vierendeel 771 kN·m (36.2 m³). Systems that follow the thrust line are the light ones; the Vierendeel pays for its open panels.",ar:"المعمل بيحط نفس البحر 24 م ونفس 60 kN/m على سبع أنظمة، كل واحد بقاعدة عمقه. أكبر العزوم: الإطار ذو المفصلين 2452 kN·m (26.6 م³ خرسانة بأعمدته)، والإطار الثابت 2531 kN·m (23.0 م³)، والكمرة المقوّسة بشداد 77 kN·m (11.1 م³)، والجمالون 61 kN·m (22.6 م³)، والفيرندل 771 kN·m (36.2 م³). الأنظمة اللي ماشية مع خط الضغط هي الخفيفة؛ والفيرندل بيدفع تمن بواكيه المفتوحة."}},{t:"lab",lab:"frame",height:480,props:{template:"studio",lockTemplate:!0,missions:h},caption:{en:"One span, one load, seven systems: switch the system, the span and the soil; the Hand method gives the range, the depth rule, the forces, the concrete and a reasoned pick.",ar:"بحر واحد وحمل واحد وسبع أنظمة: بدّل النظام والبحر والتربة؛ والحل اليدوي بيدّي المدى وقاعدة العمق والقوى والخرسانة واختيار مسبّب."}},{t:"quiz",q:{kind:"tf",q:{en:"A cantilever frame may stand on a hinged base if its footing is large enough.",ar:"الإطار الكابولي ممكن يقف على قاعدة مفصلية لو القاعدة كبيرة كفاية."},answer:!1,explain:{en:"A hinge cannot hold the cantilever's moment: the frame would rotate about it. It must be fixed.",ar:"المفصلة ماتقدرش تمسك عزم الكابولي: الإطار هيلف حواليها. لازم يبقى ثابت."}}}]},{id:"posts",title:{en:"Posts and hangers",ar:"القوائم والمعلّقات"},blocks:[{t:"p",text:{en:"Short members that carry a roof or a slab level between two systems are either **posts** (in compression, sized by their clear height $H_0$ between the two members they join — their buckling height) or **hangers** (in tension, 250 × 250). When a post would be taller than about 4 m, hang the level from above instead.",ar:"الأعضاء القصيرة اللي بتشيل سقف أو منسوب بلاطة بين نظامين يا إما **قوائم** (ضغط، بتتصمم بارتفاعها الصافي $H_0$ بين العنصرين اللي بتربطهم — وده ارتفاع انبعاجها) يا إما **معلّقات** (شد، 250 × 250). ولو القائم هيطول أكتر من حوالي 4 م، علّق المنسوب من فوق بدل كده."}},{t:"table",head:[{en:"Member",ar:"العضو"},{en:"Section",ar:"القطاع"},{en:"Bars",ar:"الحديد"}],rows:[[{en:"post, H₀ ≤ 2.5 m (short column)",ar:"قائم، H₀ ≤ 2.5 م (عمود قصير)"},"250 × 250","4Φ12"],[{en:"post, H₀ = 2.5–4 m (long column)",ar:"قائم، H₀ = 2.5–4 م (عمود طويل)"},"250 × 250","8Φ12"],[{en:"post, H₀ > 4 m (or use a hanger)",ar:"قائم، H₀ > 4 م (أو استخدم معلّق)"},{en:"b × b, b = width of the system",ar:"b × b، و b = عرض النظام"},"8Φ12"],[{en:"hanger holding a tie only",ar:"معلّق شايل شداد بس"},"250 × 250","4Φ12"],[{en:"hanger carrying a beam",ar:"معلّق شايل كمرة"},"250 × 250","8Φ12"]]},{t:"p",text:{en:"A hanger is in tension and cannot buckle, so it stays **250 × 250 whatever its height**: 4Φ12 when it only holds up the weight of a tie, 8Φ12 when a beam hangs on it. Whether that beam is dropped or upstand makes no difference — the hanger bars run into the beam and are anchored there. Still, **posts come first**: carry a level on posts, and change to hangers only where a post would be taller than 4.0 m. A taller post is a poor answer, though not a wrong one: where a lower roof would need posts of 4.5–5 m on the system beside it, extend the upper system over it and hang the lower roof instead.",ar:"المعلّق شغال شد ومش بينبعج، فبيفضل **250 × 250 مهما كان طوله**: 4Φ12 لو شايل وزن شداد بس، و 8Φ12 لو فيه كمرة متعلقة عليه. وسواء الكمرة دي ساقطة أو مقلوبة مش فارقة — أسياخ المعلّق بتدخل جوه الكمرة وبتتثبت فيها. ومع ذلك **القوائم الأول**: شيل المنسوب على قوائم، وحوّل لمعلّقات بس في المكان اللي القائم فيه هيبقى أطول من 4.0 م. والقائم الأطول من كده حل سيئ، بس مش غلط: لو سقف واطي هيحتاج قوائم 4.5–5 م على النظام اللي جنبه، مدّ النظام العالي فوقه وعلّق السقف الواطي منه بدل كده."}},{t:"p",text:{en:"A post must lean **along the resultant** of the forces it carries: rise/run $= Y/X$, force $P = \\sqrt{X^2 + Y^2}$. Otherwise it bends: a vertical post fixed at its base and pushed by $X$ at its head gets $M = X\\,H_0$ with $N = Y$ — a frame member, designed for $M$ and $N$. **Example:** $X = 60$, $Y = 45$ kN → rise/run 0.75 ($36.9^\\circ$), $P = 75$ kN in pure compression; stood vertically, 3 m high, the same post takes $M = 180$ kN·m. A 3.2 m post gets 250 × 250 with 8Φ12; a 5 m post under a 350 mm wide system 350 × 350 with 8Φ12 — or becomes a hanger.",ar:"القائم لازم يميل **مع محصلة** القوى اللي شايلها: الارتفاع/الأفقي $= Y/X$، والقوة $P = \\sqrt{X^2 + Y^2}$. غير كده بينحني: قائم رأسي مثبت من تحت وبيتزق بـ $X$ من راسه بياخد $M = X\\,H_0$ مع $N = Y$ — عضو إطار، بيتصمم على $M$ و $N$. **مثال:** $X = 60$، و $Y = 45$ kN ← الميل 0.75 ($36.9^\\circ$)، و $P = 75$ kN ضغط صافي؛ ولو اتوقّف رأسي بارتفاع 3 م، نفس القائم بياخد $M = 180$ kN·m. قائم 3.2 م بياخد 250 × 250 بـ 8Φ12؛ وقائم 5 م تحت نظام عرضه 350 مم بياخد 350 × 350 بـ 8Φ12 — أو يتحوّل لمعلّق."}},{t:"eq",tex:["\\tan\\beta = \\dfrac{Y}{X},\\qquad P = \\sqrt{X^2 + Y^2},\\qquad M = X\\,H_0"],caption:{en:"β = slope of an aligned post from the horizontal; M = moment at the base of a vertical post pushed by X at its head.",ar:"β = ميل القائم المايل مع المحصلة من الأفقي؛ و M = العزم عند قاعدة قائم رأسي بيتزق بـ X عند راسه."}},{t:"p",text:{en:"**The glazing decides the post.** Inclined glazing → the post leans along the resultant and works in pure compression. A **vertical** window → the post must stay vertical, so it bends: thicken it and design it as part of a frame for $M$ and $N$. Whole columns are leaned along the resultant (their tops towards the thrusting roof) only where the problem asks for inclined columns. Over an **arch slab** the post slope can fix the rise: with $Y = wL/2$ and $X = wL^2/(8h)$, $Y/X = 4h/L$, so posts of slope $\\tan\\beta$ need $h = (L/4)\\tan\\beta$. Under a vertical window over an arch slab a **tie** must take $X$, so that the vertical post carries vertical load only; without a tie the post becomes part of a cantilever frame.",ar:"**الشباك هو اللي بيحدد القائم.** إزاز مايل ← القائم بيميل مع المحصلة وبيشتغل ضغط صافي. شباك **رأسي** ← القائم لازم يفضل رأسي، فبينحني: تخّنه وصمّمه كجزء من إطار على $M$ و $N$. والأعمدة نفسها بتتميّل مع المحصلة (راسها ناحية السقف اللي بيزق) بس لو المسألة طالبة أعمدة مايلة. وفوق **بلاطة مقوّسة** ميل القوائم ممكن يحدد ارتفاع العقد: بـ $Y = wL/2$ و $X = wL^2/(8h)$ يبقى $Y/X = 4h/L$، فقوائم ميلها $\\tan\\beta$ محتاجة $h = (L/4)\\tan\\beta$. وتحت شباك رأسي فوق بلاطة مقوّسة لازم **شداد** ياخد $X$، علشان القائم الرأسي يشيل حمل رأسي بس؛ ومن غير شداد القائم بيبقى جزء من إطار كابولي."}},{t:"eq",tex:["\\dfrac{Y}{X} = \\dfrac{wL/2}{wL^2/(8h)} = \\dfrac{4h}{L},\\qquad h = \\dfrac{L}{4}\\,\\tan\\beta"],caption:{en:"Rise h of an arch slab whose springing force must follow posts of slope tan β (rise/run).",ar:"ارتفاع h لبلاطة مقوّسة قوة ارتكازها لازم تمشي مع قوائم ميلها tan β (الرأسي/الأفقي)."}},{t:"p",text:{en:"**Example.** A 15 m arch slab on posts sloping 1 : 2 ($\\tan\\beta = 0.5$): $h = 15/4\\times0.5 = 1.875$ m — exactly $L/8$. Check with $w = 7$ kN/m²: $Y = 7\\times15/2 = 52.5$ and $X = 7\\times15^2/(8\\times1.875) = 105$ kN/m, so $Y/X = 0.5$.",ar:"**مثال.** بلاطة مقوّسة 15 م على قوائم ميلها 1 : 2 ($\\tan\\beta = 0.5$): $h = 15/4\\times0.5 = 1.875$ م — بالظبط $L/8$. راجع بـ $w = 7$ kN/m²: $Y = 7\\times15/2 = 52.5$ و $X = 7\\times15^2/(8\\times1.875) = 105$ kN/m، يبقى $Y/X = 0.5$."}},{t:"lab",lab:"frame",height:470,props:{template:"archslab",params:{sup:"vposts"},lockTemplate:!0,missions:l},caption:{en:"An arch slab on vertical posts: the thrust bends posts and slab. Lean the posts along the springing force.",ar:"بلاطة مقوّسة على قوائم رأسية: الدفع بيحني القوائم والبلاطة. ميّل القوائم مع قوة الارتكاز."}},{t:"quiz",q:{kind:"num",q:{en:"A post with a buckling height of 3.2 m. How many Φ12 bars?",ar:"قائم ارتفاع انبعاجه 3.2 م. كام سيخ Φ12؟"},answer:8,tol:.001,explain:{en:"Between 2.5 and 4 m it is a long column, still 250 × 250, with 8Φ12.",ar:"بين 2.5 و 4 م يبقى عمود طويل، لسه 250 × 250، بـ 8Φ12."}}}]},{id:"thrust",title:{en:"Thrust without ties",ar:"الدفع من غير شدادات"},blocks:[{t:"p",text:{en:"Saw-tooth slabs and arch slabs push their supports sideways by $X$ per metre. Left untied, each **edge column** receives $F = X\\,S$ at its head and $M = X\\,S\\,H$ at its base: make it deeper and shift its footing outwards. The **interior columns** are pushed equally from both sides and balance. Where some bays are left untied, each unbalanced push $X\\,S$ lands on a column that is tied to its neighbour: the two tied columns work as one portal and share $M = X\\,S\\,H$, $M/2$ each — on each side of the untied bays. A Y-beam girder that carries the tie force $X\\,S$ along its length is designed for moment **and** tension.",ar:"البلاطات المنشارية والمقوّسة بتزق ركائزها لجنب بـ $X$ لكل متر. ولو من غير شدادات، كل **عمود طرفي** بياخد $F = X\\,S$ عند راسه و $M = X\\,S\\,H$ عند قاعدته: عمّقه ورحّل قاعدته لبره. و**الأعمدة الداخلية** بتتزق بالتساوي من الناحيتين وبتتوازن. ولو فيه بواكي اتسابت من غير شدادات، كل زقة $X\\,S$ مش متزنة بتقع على عمود مربوط بشداد مع جاره: العمودين المربوطين بيشتغلوا إطار واحد وبيقسموا $M = X\\,S\\,H$، يعني $M/2$ لكل واحد — على كل ناحية من البواكي اللي من غير شدادات. وكمرة Y اللي بتشيل قوة الشداد $X\\,S$ على طولها بتتصمم على عزم **و**شد."}},{t:"eq",tex:["F = X\\,S,\\qquad M = X\\,S\\,H,\\qquad M_{shared} = \\dfrac{M}{2}"]},{t:"p",text:{en:"**Example.** Saw-tooth slabs push $X = 18$ kN/m, frames every $S = 6$ m, columns $H = 5$ m: $F = 108$ kN and $M = 540$ kN·m at each edge column. With ties only in the two edge bays of a four-bay roof, each edge pair is pushed at its inner column and shares 540 kN·m — 270 kN·m in each of its two columns — while the middle column, between two untied bays, stays balanced.",ar:"**مثال.** بلاطات منشارية بتزق $X = 18$ kN/m، والإطارات كل $S = 6$ م، والأعمدة $H = 5$ م: $F = 108$ kN و $M = 540$ kN·m عند كل عمود طرفي. ولو الشدادات في الباكيتين الطرفيتين بس من سقف أربع بواكي، كل جوز طرفي بيتزق من عموده الداخلي وبيقسم 540 kN·m — 270 kN·m في كل عمود من عموديه — والعمود اللي في النص، بين باكيتين من غير شدادات، بيفضل متزن."}},{t:"steps",items:[{en:"**Middle column left out**: a girder at tie level spans the gap and carries the middle Y-beam. With every bay tied it also ties the two middle teeth together — tension $X\\,S = 108$ kN in the example — and is designed for moment and tension. With the edge bays untied, the edge teeth push its ends inwards and cancel that pull: the girder takes moment only, and the edge columns take $X\\,S\\,H = 540$ kN·m (deepen them, shift their footings).",ar:"**العمود اللي في النص اتشال**: كمرة على منسوب الشدادات بتغطي الفتحة وبتشيل كمرة Y اللي في النص. ولو كل البواكي بشدادات بتربط كمان السنّتين اللي في النص ببعض — شد $X\\,S = 108$ kN في المثال — وبتتصمم على عزم وشد. ولو البواكي الطرفية من غير شدادات، السنّات الطرفية بتزق أطرافها لجوه وبتلغي الشد ده: الكمرة بتاخد عزم بس، والأعمدة الطرفية بتاخد $X\\,S\\,H = 540$ kN·m (عمّقها ورحّل قواعدها)."},{en:"**Teeth at two levels**, springings at +7.50 and +4.50, $(o.w. + Y)\\,S = (4 + 26)\\times6 = 180$ kN at each springing. **Tied**: the columns are axial only, and the shared column steps from 180 kN to 360 kN below +4.50. **Untied**: the outer columns take $108\\times7.5 = 810$ and $108\\times4.5 = 486$ kN·m at their bases; the shared column is pushed one way at +7.50 and the other way at +4.50, so its moment grows from zero to $108\\times3.0 = 324$ kN·m at +4.50 and then stays constant down to the base.",ar:"**سنّات على منسوبين**، الارتكاز عند +7.50 و +4.50، و $(o.w. + Y)\\,S = (4 + 26)\\times6 = 180$ kN عند كل ارتكاز. **بشدادات**: الأعمدة محورية بس، والعمود المشترك قوته بتنط من 180 kN لـ 360 kN تحت +4.50. **من غير شدادات**: العمودين الخارجيين بياخدوا $108\\times7.5 = 810$ و $108\\times4.5 = 486$ kN·m عند قواعدهم؛ والعمود المشترك بيتزق في اتجاه عند +7.50 وفي العكس عند +4.50، فعزمه بيكبر من صفر لحد $108\\times3.0 = 324$ kN·m عند +4.50 وبعدين بيفضل ثابت لحد القاعدة."},{en:"**An untied arch slab beside simple girders**: give each girder real supports — a real hinge on the arch side and a real roller at its far end. The whole $X\\,S$ then goes into the one column under the real hinge and straight to its footing; nothing reaches the girder or the other column. Make that column about **1.5 t** ($t$ = the usual column depth) and shift its footing against the moment. Or keep the girders monolithic and make the arch-side column about **2.5 t**: the sway stiffness of a column grows with $t^3$, so it attracts $2.5^3/(2.5^3 + 1) = 94\\%$ of the push. **Example:** $X = 40$ kN/m, $S = 5$ m, a 6 m column: 200 kN and 1200 kN·m at its base; a 0.5 m column becomes 0.75 m on the real hinge, or 1.25 m by stiffness.",ar:"**بلاطة مقوّسة من غير شداد جنب كمرات بسيطة**: ادّي كل كمرة ركائز حقيقية — مفصلة حقيقية ناحية العقد وركيزة متحركة حقيقية في طرفها التاني. ساعتها $X\\,S$ كلها بتروح للعمود الواحد اللي تحت المفصلة الحقيقية ومنه للقاعدة على طول؛ ومفيش حاجة بتوصل للكمرة ولا للعمود التاني. خلّي العمود ده حوالي **1.5 t** ($t$ = عمق العمود العادي) ورحّل قاعدته عكس العزم. أو سيب الكمرات مصبوبة مع الأعمدة وخلّي عمود ناحية العقد حوالي **2.5 t**: جساءة العمود للحركة الجانبية بتكبر مع $t^3$، فبيسحب $2.5^3/(2.5^3 + 1) = 94\\%$ من الزقة. **مثال:** $X = 40$ kN/m، و $S = 5$ م، وعمود 6 م: 200 kN و 1200 kN·m عند قاعدته؛ والعمود اللي عمقه 0.5 م بيبقى 0.75 م على المفصلة الحقيقية، أو 1.25 م بالجساءة."},{en:"**An untied arch slab between two-hinged frames** pushes their knees sideways: the frames sway and their B.M.D cannot be guessed — solve them by superposition or virtual work (the indeterminate-frames episode). Across a 4 + 16 + 4 m hall a tie over the 16 m arch slab is the practical answer; without it the side bays would need frames leaning along the thrust.",ar:"**بلاطة مقوّسة من غير شداد بين إطارات ذات مفصلين** بتزق أركانهم لجنب: الإطارات بيحصلها إزاحة جانبية (Sway) ومنحنى عزومهم مايتخمنش — حلّهم بالتجميع أو بالشغل الافتراضي (حلقة الإطارات غير المحددة). وفي صالة 4 + 16 + 4 م الشداد فوق البلاطة المقوّسة الـ 16 م هو الحل العملي؛ ومن غيره البواكي الجانبية هتحتاج إطارات مايلة مع الدفع."},{en:"**Teeth parallel to the frames.** When the ridges run parallel to the frames, each tooth spans the spacing $S$ from one frame beam to the next — the frame beam is its valley beam — and the posts of the next tooth stand on the next frame beam. Its windows should then be **vertical**. With inclined windows every tooth pushes its frames sideways, out of their own plane, by $X$ per metre of frame beam: on the repeated frames the forces of two neighbouring teeth nearly balance, but the **first and the last frame** are pushed from one side only, $X\\,L$ in all. Either tie the frames together every few windows, so that the push on an end frame passes on to its neighbours, or make the two end frames **fixed-base**, widened to **500 mm**, and design them for bending about both axes. **Example:** $X = 8$ kN/m along an 18 m frame beam: $8\\times18 = 144$ kN pushes the end frame out of its plane.",ar:"**سنّات موازية للإطارات.** لما خطوط التاج تمشي موازية للإطارات، كل سنّة بحرها المسافة $S$ من كمرة إطار للي بعدها — وكمرة الإطار هي كمرة الوادي بتاعتها — وقوائم السنّة اللي بعدها واقفة على كمرة الإطار اللي بعدها. والشبابيك ساعتها لازم تبقى **رأسية**. ولو الشبابيك مايلة كل سنّة بتزق إطاراتها لجنب، خارج مستواها هي، بـ $X$ لكل متر من كمرة الإطار: على الإطارات المتكررة قوى السنّتين اللي جنب بعض بتتوازن تقريباً، لكن **أول وآخر إطار** بيتزقوا من ناحية واحدة بس، $X\\,L$ كلها. يا إما اربط الإطارات ببعض بشدادات كل كام شباك، علشان الزقة على الإطار الطرفي تعدّي للي جنبه، يا إما خلّي الإطارين الطرفيين **ثابتين الركائز**، وكبّر عرضهم لـ **500 مم**، وصمّمهم على عزم في الاتجاهين. **مثال:** $X = 8$ kN/m على طول كمرة إطار 18 م: $8\\times18 = 144$ kN بتزق الإطار الطرفي خارج مستواه."}]},{t:"quiz",q:{kind:"num",q:{en:"No ties: X = 15 kN/m, S = 5 m, edge column 6 m high. Moment at its base (kN·m)?",ar:"من غير شدادات: X = 15 kN/m، و S = 5 م، والعمود الطرفي ارتفاعه 6 م. العزم عند قاعدته (kN·m)؟"},answer:450,tol:.003,unit:"kN·m",explain:{en:"$15\\times5\\times6 = 450$ kN·m.",ar:"$15\\times5\\times6 = 450$ kN·m."}}}]},{id:"junctions",title:{en:"Where an arch slab meets other members",ar:"لما البلاطة المقوّسة تقابل عناصر تانية"},blocks:[{t:"steps",items:[{en:"**Continuous arch slabs**: equal thrusts cancel on the interior beam; a difference $\\Delta X$ bends it sideways (the arch-slab episode).",ar:"**البلاطات المقوّسة المستمرة**: الدفعين المتساويين بيلغوا بعض على الكمرة الوسطية؛ والفرق $\\Delta X$ بيحنيها أفقي (حلقة البلاطات المقوّسة)."},{en:"**A horizontal slab joined to an arch slab** receives its thrust $X$ in its plane: it becomes an eccentrically loaded member, designed for $M$ and $P$ with the interaction diagrams.",ar:"**بلاطة أفقية متوصلة ببلاطة مقوّسة** بتاخد دفعها $X$ في مستواها: بتبقى عضو عليه حمل لامركزي، بيتصمم على $M$ و $P$ بمنحنيات التفاعل."},{en:"**Inclined end beam**: set in the plane of the springing force, it receives $w_i = P + o.w.\\cos\\theta$ per metre — $\\theta$ = the angle between that plane and the vertical — and gives its supports $R_i = w_i\\,S$ along that direction. It is a **continuous beam over the inclined posts or columns**: hogging over them and sagging between, so top bars over the supports and bottom bars in the spans. Columns at the slope of $R_i$ take no moment, and **no tie** is added — a tie would pull $X$ out and turn the resultant vertical, off their axis. Only a **vertical** column under the beam needs a tie (or it bends).",ar:"**كمرة طرفية مائلة**: لو اتحطت في مستوى قوة الارتكاز، بتاخد $w_i = P + o.w.\\cos\\theta$ لكل متر — و $\\theta$ = الزاوية بين المستوى ده والرأسي — وبتدّي ركائزها $R_i = w_i\\,S$ في نفس الاتجاه. وهي **كمرة مستمرة على القوائم أو الأعمدة المايلة**: عزم سالب فوقها وموجب بينها، يعني حديد علوي فوق الركائز وسفلي في البحور. والأعمدة اللي على ميل $R_i$ مابتاخدش عزم، و**مفيش شداد** بيتحط — الشداد هيسحب $X$ ويخلّي المحصلة رأسية، بره محورها. العمود **الرأسي** بس تحت الكمرة هو اللي محتاج شداد (أو بينحني)."}]},{t:"eq",tex:["w_i = P + o.w.\\cos\\theta,\\qquad R_i = w_i\\,S"],caption:{en:"P = springing force per metre, √(X² + Y²); θ = angle between the plane of the beam (the direction of P) and the vertical; S = spacing of the supports.",ar:"P = قوة الارتكاز لكل متر، √(X² + Y²)؛ و θ = الزاوية بين مستوى الكمرة (اتجاه P) والرأسي؛ و S = المسافة بين الركائز."}},{t:"p",text:{en:"**Example.** The 14 m arch slab of its episode ($P = 70.54$ kN/m, rising at $29.74^\\circ$ above the horizontal, so $\\theta = 90^\\circ - 29.74^\\circ = 60.26^\\circ$ from the vertical) on an inclined end beam weighing 5.0 kN/m, supports every 5 m: $w_i = 70.54 + 5.0\\times0.496 = 73.02$ kN/m, $R_i = 365.1$ kN along the springing direction.",ar:"**مثال.** البلاطة المقوّسة 14 م بتاعة حلقتها ($P = 70.54$ kN/m، طالعة بزاوية $29.74^\\circ$ فوق الأفقي، يعني $\\theta = 90^\\circ - 29.74^\\circ = 60.26^\\circ$ من الرأسي) على كمرة طرفية مائلة وزنها 5.0 kN/m، والركائز كل 5 م: $w_i = 70.54 + 5.0\\times0.496 = 73.02$ kN/m، و $R_i = 365.1$ kN في اتجاه الارتكاز."}},{t:"p",text:{en:"**A flat slab next to a sloping or arch slab.** At the edge where they meet no horizontal (L-leg) beam is needed: the flat slab itself acts as the horizontal beam and takes $X$ in its plane (on to the tie, at a saw-tooth). Make it about **50 mm thicker** against buckling and give it **two equal meshes**. Per 1 m strip it carries the simple-span $M$; with the thrust on **one** edge its normal force falls linearly from $X$ to zero, so the mid-span section is designed for $M$ with $P = X/2$; with arch slabs on **both** edges $P = X$ all along. Design with the interaction diagrams. **Example:** a flat strip of 4.0 m between two arch slabs, $w_s = 9$ kN/m², $X = 60$ kN/m: $M = 9\\times4^2/8 = 18$ kN·m/m with $P = 60$ kN/m; with an arch slab on one side only, $P = 30$ kN/m. A 130 mm slab becomes 180 mm. The push can also be a **pull**: a sloping slab whose posts lean outwards — their feet under the slab, their tops leaning out past the ridge — pulls its low support **inwards**, so a flat strip on that side is in **tension**. Neglect that tension and design the strip for its simple-span moment alone: a 2.4 m strip with $w_s = 9$ kN/m² takes $M = 9\\times2.4^2/8 = 6.48$ kN·m/m.",ar:"**بلاطة أفقية جنب بلاطة مايلة أو مقوّسة.** عند الحرف اللي بيتقابلوا فيه مش محتاجين كمرة أفقية (رجل الـ L): البلاطة الأفقية نفسها بتشتغل الكمرة الأفقية وبتاخد $X$ في مستواها (وتوصّله للشداد في المنشاري). تخّنها حوالي **50 مم** ضد الانبعاج وادّيها **شبكتين متساويتين**. ولكل شريحة 1 م بتشيل $M$ البحر البسيط؛ ولو الدفع على حرف **واحد** قوتها العمودية بتقل خطياً من $X$ لصفر، فقطاع نص البحر بيتصمم على $M$ مع $P = X/2$؛ ولو فيه بلاطات مقوّسة على **الحرفين** $P = X$ على طولها. وصمّم بمنحنيات التفاعل. **مثال:** شريحة أفقية 4.0 م بين بلاطتين مقوّستين، و $w_s = 9$ kN/m²، و $X = 60$ kN/m: $M = 9\\times4^2/8 = 18$ kN·m/m مع $P = 60$ kN/m؛ ولو البلاطة المقوّسة من ناحية واحدة بس، $P = 30$ kN/m. والبلاطة اللي كانت 130 مم بتبقى 180 مم. والزقة ممكن تبقى **شدّة**: بلاطة مايلة قوائمها مايلة لبره — رجليها تحت البلاطة وروسها طالعة لبره بعد التاج — بتشد ركيزتها الواطية **لجوه**، فالشريحة الأفقية اللي في الناحية دي بتبقى **شد**. اهمل الشد ده وصمّم الشريحة على عزم البحر البسيط بس: شريحة 2.4 م و $w_s = 9$ kN/m² بتاخد $M = 9\\times2.4^2/8 = 6.48$ kN·m/m."}},{t:"table",head:[{en:"Arch-slab support",ar:"ركيزة البلاطة المقوّسة"},{en:"Beam",ar:"الكمرة"},{en:"Column (spacing S)",ar:"العمود (كل S)"},{en:"Column depth",ar:"عمق العمود"}],rows:[[{en:"end beam, tied",ar:"كمرة طرفية، بشداد"},{en:"L-beam, $w_{VL} = o.w. + Y$; tie $X\\,S$",ar:"كمرة L، $w_{VL} = o.w. + Y$؛ والشداد $X\\,S$"},{en:"$R_{VL} = (o.w. + Y)\\,S$; no moment, no shift",ar:"$R_{VL} = (o.w. + Y)\\,S$؛ من غير عزم ولا ترحيل"},"$H/(10 \\to 12)$"],[{en:"end beam, untied",ar:"كمرة طرفية، من غير شداد"},{en:"$w_{VL} = o.w. + Y$, $w_{HL} = X$",ar:"$w_{VL} = o.w. + Y$، و $w_{HL} = X$"},{en:"also $R_{HL} = X\\,S$ → moment; footing shifted outwards",ar:"وكمان $R_{HL} = X\\,S$ ← عزم؛ والقاعدة مترحّلة لبره"},"$1.5\\,H/(10 \\to 12)$"],[{en:"interior beam, equal slabs",ar:"كمرة وسطية، بلاطات متساوية"},{en:"vertical beam only, $b = 250$, $t = S/12 + 150$ mm; $w_{VL} = o.w. + 2Y$",ar:"كمرة رأسية بس، $b = 250$، و $t = S/12 + 150$ مم؛ و $w_{VL} = o.w. + 2Y$"},{en:"$R_{VL} = (o.w. + 2Y)\\,S$; no moment",ar:"$R_{VL} = (o.w. + 2Y)\\,S$؛ من غير عزم"},"$H/(10 \\to 12)$"],[{en:"interior beam, unequal slabs",ar:"كمرة وسطية، بلاطات مختلفة"},{en:"vertical beam only, $b \\ge 400$; $w_{VL} = o.w. + Y_1 + Y_2$, $w_{HL} = \\Delta X$ — bending about both axes",ar:"كمرة رأسية بس، $b \\ge 400$؛ و $w_{VL} = o.w. + Y_1 + Y_2$، و $w_{HL} = \\Delta X$ — عزم في اتجاهين"},{en:"$R_{VL} = (o.w. + Y_1 + Y_2)\\,S$, $R_{HL} = \\Delta X\\,S$ → moment",ar:"$R_{VL} = (o.w. + Y_1 + Y_2)\\,S$، و $R_{HL} = \\Delta X\\,S$ ← عزم"},{en:"designed for M and P",ar:"بيتصمم على M و P"}]],caption:{en:"Per metre of arch slab: Y = w_s·L/2, X = w_s·L²/(8h); o.w. = own weight of the beam per metre; H = column height.",ar:"لكل متر من البلاطة المقوّسة: Y = w_s·L/2، و X = w_s·L²/(8h)؛ و o.w. = وزن الكمرة لكل متر؛ و H = ارتفاع العمود."}},{t:"p",text:{en:"**Example — two unequal arch slabs on one interior beam**, $w_s = 6$ kN/m²: 12 m with $h = 2.0$ m ($Y_1 = 36$, $X_1 = 54$ kN/m) and 9 m with $h = 1.5$ m ($Y_2 = 27$, $X_2 = 40.5$ kN/m), columns every $S = 6$ m. The beam is vertical only, 400 wide and $6/12 + 0.15 = 0.65$ m deep, weighing $1.4\\times0.4\\times0.65\\times25 = 9.1$ kN/m: $w_{VL} = 9.1 + 36 + 27 = 72.1$ kN/m and $w_{HL} = 54 - 40.5 = 13.5$ kN/m. Each column: $R_{VL} = 432.6$ kN and $R_{HL} = 81$ kN.",ar:"**مثال — بلاطتين مقوّستين مختلفتين على كمرة وسطية واحدة**، و $w_s = 6$ kN/m²: 12 م بـ $h = 2.0$ م ($Y_1 = 36$، و $X_1 = 54$ kN/m) و 9 م بـ $h = 1.5$ م ($Y_2 = 27$، و $X_2 = 40.5$ kN/m)، والأعمدة كل $S = 6$ م. الكمرة رأسية بس، عرضها 400 وعمقها $6/12 + 0.15 = 0.65$ م، ووزنها $1.4\\times0.4\\times0.65\\times25 = 9.1$ kN/m: $w_{VL} = 9.1 + 36 + 27 = 72.1$ kN/m و $w_{HL} = 54 - 40.5 = 13.5$ kN/m. وكل عمود: $R_{VL} = 432.6$ kN و $R_{HL} = 81$ kN."}},{t:"p",text:{en:"**At an expansion joint** a saw-tooth or arch slab ends on twin frames or twin columns sharing one footing. Either turn the horizontal leg of the L-shaped valley or springing beam **inwards**, away from the joint, or leave the leg out and use a **vertical beam only** — usually 400 mm wide — designed for the vertical and the horizontal load together (bending about both axes).",ar:"**عند فاصل التمدد** البلاطة المنشارية أو المقوّسة بتنتهي على إطارين توأم أو عمودين توأم على قاعدة واحدة. يا إما تلف الرجل الأفقية لكمرة الـ L (كمرة الوادي أو الارتكاز) **لجوه**، بعيد عن الفاصل، يا إما تشيل الرجل وتستخدم **كمرة رأسية بس** — عرضها عادة 400 مم — بتتصمم على الحمل الرأسي والأفقي مع بعض (عزم في اتجاهين)."}},{t:"quiz",q:{kind:"num",q:{en:"Inclined end beam: P = 60 kN/m, own weight 6 kN/m, θ = 30° from the vertical. Load w_i (kN/m)?",ar:"كمرة طرفية مائلة: P = 60 kN/m، ووزنها 6 kN/m، و θ = 30° من الرأسي. الحمل w_i (kN/m)؟"},answer:65.196,tol:.003,unit:"kN/m",explain:{en:"$60 + 6\\cos30^\\circ = 60 + 5.20 = 65.2$ kN/m.",ar:"$60 + 6\\cos30^\\circ = 60 + 5.20 = 65.2$ kN/m."}}}]},{id:"levels",title:{en:"Two roof levels in one hall",ar:"منسوبين للسقف في صالة واحدة"},blocks:[{t:"p",text:{en:"A hall whose roof steps from one level to another can often keep **one frame** for both parts. The step $\\Delta$ between the two slab levels decides how:",ar:"الصالة اللي سقفها بينزل من منسوب لمنسوب كتير بتقدر تفضل على **إطار واحد** للجزئين. والفرق $\\Delta$ بين منسوبين البلاطتين هو اللي بيحدد إزاي:"}},{t:"steps",items:[{en:"**$\\Delta \\le 2.0$ m**: the frame carries both slabs directly. The lower slab sits on **upstand beams**, so the frame grows no deeper than needed, and the frame beam must reach from the upper slab down below the lower one: $t \\ge \\Delta + t_s$ ($t_s$ = the lower slab).",ar:"**$\\Delta \\le 2.0$ م**: الإطار بيشيل البلاطتين مباشرة. البلاطة الواطية بتقعد على **كمرات مقلوبة**، علشان الإطار مايتعمقش أكتر من اللازم، وكمرة الإطار لازم توصل من البلاطة العالية لحد تحت الواطية: $t \\ge \\Delta + t_s$ ($t_s$ = البلاطة الواطية)."},{en:"**$\\Delta > 2.0$ m**: the frame carries one slab directly; the other stands on **posts** (or hangs on **hangers**) with a **linking beam** (كمرة تربيط) along their heads to take the slab or its ribs. The frame depth then follows the span alone.",ar:"**$\\Delta > 2.0$ م**: الإطار بيشيل بلاطة واحدة مباشرة؛ والتانية بتقف على **قوائم** (أو بتتعلق على **معلّقات**) و**كمرة تربيط** على روسهم بتشيل البلاطة أو أعصابها. وعمق الإطار ساعتها بيمشي مع البحر بس."},{en:"Where nothing may stand under part of the roof, shape the frame to the roof — a gable with its ridge off-centre, or a trapezoid — and hang the low slabs from it: a **two-hinged inclined frame**, solved by virtual work.",ar:"ولو ممنوع أي حاجة تقف تحت جزء من السقف، شكّل الإطار على شكل السقف — جمالوني تاجه مش في النص، أو شبه منحرف — وعلّق البلاطات الواطية منه: **إطار مايل ذو مفصلين**، بيتحل بالشغل الافتراضي."},{en:"**Levels that alternate from bay to bay** (high, low, high… between successive frames, each step within 2.0 m): every frame carries a high slab on one side and a low one on the other; the bars of each bay are hooked into the two frames that carry it, and the secondary beams of the low bays are upstand.",ar:"**مناسيب بتتبادل من باكية للتانية** (عالي، واطي، عالي… بين الإطارات ورا بعض، وكل درجة في حدود 2.0 م): كل إطار شايل بلاطة عالية من ناحية وواطية من التانية؛ وأسياخ كل باكية بتتجنّش جوه الإطارين اللي شايلينها، والكمرات المتشالة في البواكي الواطية مقلوبة."}]},{t:"eq",tex:["\\Delta \\le 2.0\\ \\text{m}:\\qquad t \\ge \\Delta + t_s"],caption:{en:"One frame carrying two slab levels: Δ = level difference, t_s = thickness of the lower slab, t = depth of the frame beam.",ar:"إطار واحد شايل منسوبين بلاطات: Δ = فرق المنسوب، و t_s = تخانة البلاطة الواطية، و t = عمق كمرة الإطار."}},{t:"p",text:{en:"**Example.** An 18 m two-hinged frame, slabs 140 mm thick. Slabs at +8.20 and +7.00: $\\Delta = 1.20$ m → $t \\ge 1.20 + 0.14 = 1.34$ m, and $L/(12 \\to 14) = 1.50 \\to 1.29$ m → **1.40 m** satisfies both. A step of 1.80 m would need $t \\ge 1.94$ m — deeper than $L/12 = 1.50$ m: the step governs. Slabs at +10.00 and +7.00: $\\Delta = 3.0 > 2.0$ m → the frame carries the +7.00 slab, and posts on its beam carry a linking beam 0.50 m deep under the +10.00 slab: clear height $10.00 - 0.50 - 7.00 = 2.50$ m → 250 × 250 with 4Φ12.",ar:"**مثال.** إطار ذو مفصلين 18 م، والبلاطات تخانتها 140 مم. بلاطات عند +8.20 و +7.00: $\\Delta = 1.20$ م ← $t \\ge 1.20 + 0.14 = 1.34$ م، و $L/(12 \\to 14) = 1.50 \\to 1.29$ م ← **1.40 م** بتحقق الاتنين. ودرجة 1.80 م كانت هتحتاج $t \\ge 1.94$ م — أعمق من $L/12 = 1.50$ م: الدرجة هي اللي بتحكم. وبلاطات عند +10.00 و +7.00: $\\Delta = 3.0 > 2.0$ م ← الإطار بيشيل بلاطة +7.00، وقوائم على كمرته بتشيل كمرة تربيط عمقها 0.50 م تحت بلاطة +10.00: الارتفاع الصافي $10.00 - 0.50 - 7.00 = 2.50$ م ← 250 × 250 بـ 4Φ12."}},{t:"p",text:{en:"**Stepped elevations.** Two simple girders of 9 m side by side at different levels ($t = 9/10 = 0.9$ m, $w = 40$ kN/m) share their middle column: it receives $R = 40\\times9/2 = 180$ kN at each level — 180 kN above the lower roof and $2R = 360$ kN below it. A wide bay on a two-hinged frame beside a narrow bay on a simple girder: the girder rests on the frame column and needs no corbel — its bars run into the column and end there, **straight** or with a short hook, but are never bent down along it, so the joint passes no moment; the column takes the reaction with the additional moment of buckling, and the girder's other column, hinged at its top, carries no moment at all. Two frames at different levels are often analysed in practice as one continuous frame, by computer; by hand they are best kept **separate**: a two-hinged frame (moment distribution) and a roller–fixed frame (virtual work) whose roller end sits on a short corbel of the first frame's column — with no horizontal reaction at the roller, the fixed column of the second frame has a constant moment.",ar:"**الواجهات اللي فيها درجات.** كمرتين بسيطتين 9 م جنب بعض على منسوبين مختلفين ($t = 9/10 = 0.9$ م، و $w = 40$ kN/m) بيشتركوا في العمود اللي في النص: بياخد $R = 40\\times9/2 = 180$ kN عند كل منسوب — 180 kN فوق السقف الواطي و $2R = 360$ kN تحته. وباكية عريضة على إطار ذو مفصلين جنب باكية ضيقة على كمرة بسيطة: الكمرة بتقعد على عمود الإطار ومش محتاجة كابولي قصير — أسياخها بتدخل العمود وبتنتهي جواه، **مستقيمة** أو بجنش قصير، من غير ما تتني لتحت على طوله، فالوصلة مابتنقلش عزم؛ والعمود بياخد رد الفعل مع العزم الإضافي للانبعاج، والعمود التاني للكمرة، المفصلي من فوق، مفيهوش عزم خالص. وإطارين على منسوبين مختلفين عملياً كتير بيتحلوا كإطار مستمر واحد بالكمبيوتر؛ وباليد الأحسن **يتفصلوا**: إطار ذو مفصلين (توزيع العزوم) وإطار متحركة–ثابتة (الشغل الافتراضي) طرفه المتحرك قاعد على كابولي قصير طالع من عمود الإطار الأول — ومن غير رد فعل أفقي عند الركيزة المتحركة، العمود الثابت في الإطار التاني عزمه ثابت على طوله."}},{t:"quiz",q:{kind:"num",q:{en:"One frame carries slabs at +9.40 and +8.00; the lower slab is 150 mm thick. Smallest depth of the frame beam (m)?",ar:"إطار واحد شايل بلاطات عند +9.40 و +8.00؛ والبلاطة الواطية تخانتها 150 مم. أقل عمق لكمرة الإطار (م)؟"},answer:1.55,tol:.01,unit:"m",explain:{en:"$\\Delta = 1.40 \\le 2.0$ m → $t \\ge 1.40 + 0.15 = 1.55$ m.",ar:"$\\Delta = 1.40 \\le 2.0$ م ← $t \\ge 1.40 + 0.15 = 1.55$ م."}}}]},{id:"carried",title:{en:"One system standing on another",ar:"نظام واقف على نظام"},blocks:[{t:"p",text:{en:"Halls at two levels put one system on top of another. Keep the joint between them simple, so that each can be solved on its own:",ar:"الصالات اللي على منسوبين بتحط نظام فوق نظام. خلّي الوصلة بينهم بسيطة، علشان كل واحد يتحل لوحده:"}},{t:"steps",items:[{en:"**A frame standing on a girder or on another frame** is made **two-hinged — even up to 24 m**. Fixed feet would close the two into one closed frame, highly indeterminate and bending the carrying member. The hinges pass no moment, only $Y$ (down) and $X$ (outwards): the carrying girder becomes the tie of the frame — designed for its continuous-beam moment **and** the tension $X$ — and the columns under the hinges are in compression.",ar:"**إطار واقف على كمرة أو على إطار تاني** بيتعمل **ذو مفصلين — حتى لحد 24 م**. الرجلين الثابتين هيقفلوا الاتنين في إطار مقفول واحد، غير محدد بدرجة عالية وبيحني العنصر الشايل. والمفصلات مابتنقلش عزم، بس $Y$ (لتحت) و $X$ (لبره): الكمرة الشايلة بتبقى شداد الإطار — بتتصمم على عزمها ككمرة مستمرة **و**الشد $X$ — والأعمدة اللي تحت المفصلات ضغط."},{en:"**Stacked frames** (the upper one standing on the knees of the lower): solve the carried frame first, then load the lower one with its reactions reversed — $Y$ down and $X$ outwards at each knee — together with its own beam load. Standing exactly on the knees, the two $Y$ go straight down the columns and the outward pair stays in the lower beam as tension; the moments of the lower frame do not change.",ar:"**إطارات فوق بعض** (اللي فوق واقف على أركان اللي تحت): حل الإطار المحمول الأول، وبعدين حمّل اللي تحت بردود أفعاله معكوسة — $Y$ لتحت و $X$ لبره عند كل ركن — مع حمل كمرته هو. ولو واقف على الأركان بالظبط، الـ $Y$ الاتنين بينزلوا في الأعمدة على طول والزوج اللي لبره بيفضل في الكمرة اللي تحت شد؛ وعزوم الإطار اللي تحت مابتتغيرش."},{en:"A **cantilever frame** carried this way must be **fixed** to the system below — on a hinge it is a mechanism. Its moments come straight from statics; with a symmetric roof spanning between two of them each takes $Y = \\Sigma W/2$. A cantilever frame that carries another system at its tip is deep: $t_c = L_c/(2 \\to 3)$ — 2.25 to 1.5 m for $L_c = 4.5$ m (the $L_c/5$ of a canopy arm is for an arm loaded along its length).",ar:"**الإطار الكابولي** المحمول بالشكل ده لازم **يتثبت** في النظام اللي تحته — على مفصلة يبقى ميكانيزم. وعزومه بتطلع من الاستاتيكا على طول؛ ولو سقف متماثل بحره بين اتنين منهم كل واحد بياخد $Y = \\Sigma W/2$. والإطار الكابولي اللي شايل نظام تاني عند طرفه بيبقى عميق: $t_c = L_c/(2 \\to 3)$ — من 2.25 لـ 1.5 م لـ $L_c = 4.5$ م (والـ $L_c/5$ بتاعة ذراع المظلة لذراع محمّل على طوله)."},{en:"A **girder** standing on another system — a saw-tooth girder, say — sits on **real supports**, or girder and support close into one frame. With a tie: hinge + roller (the tie takes $X$ and stops the sway). Without a tie: hinge + hinge, to limit the sway — and the cantilever frames under it then receive $Y_1$ and the thrust $X\\,S$ at their tips: the column moment $Y_1 L_c$ at the top becomes $Y_1 L_c - X\\,S\\,H$ at the base and may change sign, so reinforce both faces of the column for tension.",ar:"**الكمرة** الواقفة على نظام تاني — كمرة منشارية مثلاً — بتقعد على **ركائز حقيقية**، غير كده الكمرة والركيزة بيقفلوا في إطار واحد. بشداد: ركيزة مفصلية + متحركة (الشداد بياخد $X$ وبيمنع الإزاحة الجانبية). ومن غير شداد: مفصلية + مفصلية، علشان تقلل الإزاحة الجانبية — والإطارات الكابولي اللي تحتها بتاخد ساعتها $Y_1$ والدفع $X\\,S$ عند أطرافها: عزم العمود $Y_1 L_c$ فوق بيبقى $Y_1 L_c - X\\,S\\,H$ عند القاعدة وممكن يغيّر إشارته، فسلّح الوشين للشد."},{en:"An **arch girder beside a lower frame**: extend the frame column up to carry the arch end and anchor the upper column bars $L_d = 40\\Phi$ into it — 880 mm for Φ22. Or make the lower frame roller–fixed, its roller end on a short corbel of the shared column; that column is then designed for $P$ and $M_{add}$.",ar:"**كمرة مقوّسة جنب إطار أوطى**: طوّل عمود الإطار لفوق يشيل طرف العقد وثبّت أسياخ العمود اللي فوق $L_d = 40\\Phi$ جواه — 880 مم لـ Φ22. أو خلّي الإطار اللي تحت متحركة–ثابتة، وطرفه المتحرك على كابولي قصير من العمود المشترك؛ والعمود ده ساعتها بيتصمم على $P$ و $M_{add}$."}]},{t:"p",text:{en:"**Example — two cantilever frames on a two-hinged frame.** Lower frame $L = 15$ m, $h = 5$ m, $w = 40$ kN/m on its beam. On each knee stands a cantilever frame: a 3 m column and a 3.5 m arm pointing inwards; the untied roof between the arm tips gives each tip $P = 100$ kN down and $X_t = 30$ kN outwards. Each hinge: $V = (40\\times15 + 2\\times100)/2 = 400$ kN. To find the thrust $H$ quickly, put $M = 0$ in the lower beam at $L/5 = 3$ m from the knee and take moments of everything on its left about that point: $-400\\times3 + 5H + 120\\times1.5 - 100\\times0.5 + 30\\times3 = 0$ → $H = 196$ kN. At the knee: lower column $196\\times5 = 980$ kN·m; upper column $100\\times3.5 - 30\\times3 = 260$ kN·m, turning the joint the other way; the beam end balances the two: $980 - 260 = 720$ kN·m. Check at the assumed hinge: $-720 + 300\\times3 - 40\\times3^2/2 = 0$. Mid-span: $-720 + 300\\times7.5 - 40\\times7.5^2/2 = 405$ kN·m.",ar:"**مثال — إطارين كابولي على إطار ذو مفصلين.** الإطار اللي تحت $L = 15$ م، و $h = 5$ م، و $w = 40$ kN/m على كمرته. على كل ركن واقف إطار كابولي: عمود 3 م وذراع 3.5 م لجوه؛ والسقف اللي من غير شداد بين طرفين الذراعين بيدّي كل طرف $P = 100$ kN لتحت و $X_t = 30$ kN لبره. كل مفصلة: $V = (40\\times15 + 2\\times100)/2 = 400$ kN. وعلشان تجيب الدفع $H$ بسرعة، حط $M = 0$ في الكمرة اللي تحت على بعد $L/5 = 3$ م من الركن وخد عزوم كل اللي على شماله حوالين النقطة دي: $-400\\times3 + 5H + 120\\times1.5 - 100\\times0.5 + 30\\times3 = 0$ ← $H = 196$ kN. عند الركن: العمود اللي تحت $196\\times5 = 980$ kN·m؛ والعمود اللي فوق $100\\times3.5 - 30\\times3 = 260$ kN·m، بيلف العقدة في الاتجاه التاني؛ وطرف الكمرة بيوازن الاتنين: $980 - 260 = 720$ kN·m. مراجعة عند المفصلة المفروضة: $-720 + 300\\times3 - 40\\times3^2/2 = 0$. ونص البحر: $-720 + 300\\times7.5 - 40\\times7.5^2/2 = 405$ kN·m."}},{t:"quiz",q:{kind:"mcq",q:{en:"A 20 m frame must stand on a continuous girder. Its feet are made…",ar:"إطار 20 م لازم يقف على كمرة مستمرة. رجليه بتتعمل…"},options:[{en:"hinged: the girder takes its thrust as a tie",ar:"مفصلية: الكمرة بتاخد دفعه كشداد"},{en:"fixed, for smaller moments",ar:"ثابتة، علشان العزوم تبقى أصغر"},{en:"one fixed, one on a roller",ar:"واحدة ثابتة وواحدة متحركة"}],answer:0,explain:{en:"Two-hinged even up to 24 m: fixed feet would close frame and girder into one closed frame and bend the girder.",ar:"ذو مفصلين حتى لحد 24 م: الرجلين الثابتين هيقفلوا الإطار والكمرة في إطار مقفول واحد وهيحنوا الكمرة."}}}]},{id:"columns",title:{en:"Column moments and which way to shift the footing",ar:"عزوم الأعمدة والقاعدة تترحّل في أنهي اتجاه"},blocks:[{t:"p",text:{en:"An overhang along the side of a hall: up to $L_c = 2.0$ m a **cantilever slab** is enough; beyond 2.0 m use a **cantilever frame** (an arm of the frame itself). The cantilever slab hangs on the edge beam, which twists and hands every frame column a concentrated moment at the slab level:",ar:"كابولي على جنب الصالة: لحد $L_c = 2.0$ م **بلاطة كابولي** كفاية؛ وبعد 2.0 م استخدم **إطار كابولي** (ذراع طالع من الإطار نفسه). وبلاطة الكابولي متعلقة على الكمرة الطرفية، اللي بتلتوي وبتسلّم كل عمود إطار عزم مركز عند منسوب البلاطة:"}},{t:"eq",tex:["M_c = \\dfrac{w_s\\,L_c^2}{2}\\,S"],caption:{en:"w_s = slab load (kN/m²), L_c = cantilever length, S = spacing of the frames.",ar:"w_s = حمل البلاطة (kN/m²)، و L_c = طول الكابولي، و S = المسافة بين الإطارات."}},{t:"p",text:{en:"The column's B.M.D jumps by $M_c$ at the slab level. A column with no horizontal restraint at its top — a girder resting on it, for instance — keeps $M_c$ unchanged down to its base, and its footing is shifted towards the cantilever by $e = M_c/P$. **Example:** $w_s = 9$ kN/m², $L_c = 1.8$ m, frames every 6 m: $M_c = 9\\times1.8^2/2\\times6 = 87.5$ kN·m; with $P = 700$ kN the footing moves $87.5/700 = 0.125$ m outwards.",ar:"منحنى عزوم العمود بينط بـ $M_c$ عند منسوب البلاطة. والعمود اللي راسه مش ممسوكة أفقياً — كمرة قاعدة عليه مثلاً — بيفضل عليه $M_c$ زي ما هو لحد قاعدته، وقاعدته بتترحّل ناحية الكابولي بمسافة $e = M_c/P$. **مثال:** $w_s = 9$ kN/m²، و $L_c = 1.8$ م، والإطارات كل 6 م: $M_c = 9\\times1.8^2/2\\times6 = 87.5$ kN·m؛ ومع $P = 700$ kN القاعدة بتتحرك $87.5/700 = 0.125$ م لبره."}},{t:"p",text:{en:"**Which way to shift a footing**: against the reactions the base must supply — against the base thrust $X$, or against the fixing moment $M$ — which moves it towards the side where the column force really lands, by $X(t_1 + t_2)/P$ or $M/P$:",ar:"**القاعدة تترحّل في أنهي اتجاه**: عكس ردود الأفعال اللي القاعدة لازم تدّيها — عكس الدفع الأفقي $X$ عند القاعدة، أو عكس عزم التثبيت $M$ — وده بيوديها ناحية المكان اللي قوة العمود بتقع فيه فعلاً، بمسافة $X(t_1 + t_2)/P$ أو $M/P$:"}},{t:"table",head:[{en:"Column",ar:"العمود"},{en:"At its base",ar:"عند قاعدته"},{en:"Footing",ar:"القاعدة"}],rows:[[{en:"gable or portal on two hinges, closed by a tie",ar:"جمالوني أو إطار بوابي على مفصلتين، مقفول بشداد"},{en:"X = 0",ar:"X = 0"},{en:"not shifted",ar:"من غير ترحيل"}],[{en:"portal on two hinges",ar:"إطار بوابي على مفصلتين"},{en:"X inwards",ar:"X لجوه"},{en:"shifted outwards",ar:"مترحّلة لبره"}],[{en:"fixed column with an arm loaded at its tip",ar:"عمود ثابت بذراع محمّل عند طرفه"},{en:"fixing moment M resisting the overturn of the arm",ar:"عزم تثبيت M بيقاوم انقلاب الذراع"},{en:"shifted towards the arm",ar:"مترحّلة ناحية الذراع"}],[{en:"the same column loaded near the knee and pulled back at the tip",ar:"نفس العمود محمّل قريب من الركن ومشدود لورا عند الطرف"},{en:"M reversed",ar:"M معكوس"},{en:"shifted away from the arm",ar:"مترحّلة بعيد عن الذراع"}],[{en:"the same column with its tip pulled outwards (arm in tension)",ar:"نفس العمود وطرفه مشدود لبره (الذراع في شد)"},{en:"M grows by X·S·H; with a strut to the next column it stays M_B",ar:"M بيزيد بـ X·S·H؛ وبدعامة للعمود اللي بعده بيفضل M_B"},{en:"shifted further towards the arm; e = M_B/N with the strut",ar:"مترحّلة أكتر ناحية الذراع؛ و e = M_B/N بالدعامة"}],[{en:"column of a tied system (tied arch slab, tied saw-tooth)",ar:"عمود نظام بشداد (بلاطة مقوّسة أو منشاري بشداد)"},{en:"P and M_add only",ar:"P و M_add بس"},{en:"not shifted",ar:"من غير ترحيل"}],[{en:"column of an untied system",ar:"عمود نظام من غير شداد"},{en:"P and M_ext",ar:"P و M_ext"},{en:"shifted outwards, against the fixing moment",ar:"مترحّلة لبره، عكس عزم التثبيت"}]],caption:{en:"M_add = additional moment of buckling; M_ext = external moment of the thrust, growing from the springing level down to the base.",ar:"M_add = العزم الإضافي للانبعاج؛ و M_ext = العزم الخارجي من الدفع، بيكبر من منسوب الارتكاز لتحت لحد القاعدة."}},{t:"p",text:{en:"So the columns come in two kinds: those of a **tied** system carry $P$ with only the additional moment of buckling, $M_{add}$; those of an **untied** system also carry an external moment $M_{ext}$ from the thrust — they are deepened and their footings shifted.",ar:"يعني الأعمدة نوعين: أعمدة النظام اللي **بشداد** بتشيل $P$ مع العزم الإضافي للانبعاج $M_{add}$ بس؛ وأعمدة النظام اللي **من غير شداد** بتشيل كمان عزم خارجي $M_{ext}$ من الدفع — بتتعمّق وقواعدها بتترحّل."}},{t:"p",text:{en:"**An arm pulled at its tip.** A tooth whose glazing leans **outwards** — its posts standing on a second column beyond the tooth — is hinged at the tip of a cantilever frame and pulls that tip **away** from its column with $X\\,S$. The arm is then in tension (designed for $M$ with $T$, like a chord in tension), and the pull **adds** to the moment of the vertical loads at the base: $M_A = M_B + X\\,S\\,H$ — the footing must move still further towards the arm. The cure is a pin-ended **strut** from the tip to the second column, where the posts push the other way: the two horizontal forces meet in the strut, which carries $X\\,S$ in compression. In the hand solution the cantilever column then keeps the constant root moment $M_B$ all the way down to its base (footing shift $e = M_B/N$), and the second column carries axial load only (no shift). The strut is a short member designed for axial load alone, buckling neglected, with at least 0.8% of steel.",ar:"**ذراع مشدود من طرفه.** سنّة إزازها مايل **لبره** — قوائمها واقفة على عمود تاني بعد السنّة — بتبقى متمفصلة عند طرف إطار كابولي وبتشد الطرف ده **بعيد** عن عموده بـ $X\\,S$. الذراع ساعتها في شد (بيتصمم على $M$ مع $T$، زي الوتر المشدود)، والشدّة **بتتزوّد** على عزم الأحمال الرأسية عند القاعدة: $M_A = M_B + X\\,S\\,H$ — والقاعدة لازم تترحّل أكتر ناحية الذراع. والعلاج **دعامة ضغط** متمفصلة الطرفين من الطرف للعمود التاني، اللي القوائم بتزقه في الاتجاه العكسي: القوتين الأفقيتين بيتقابلوا في الدعامة، وهي بتشيل $X\\,S$ ضغط. وفي الحل اليدوي العمود الكابولي ساعتها بيفضل عليه عزم الجذر $M_B$ ثابت لحد قاعدته (ترحيل القاعدة $e = M_B/N$)، والعمود التاني بيشيل حمل محوري بس (من غير ترحيل). والدعامة عضو قصير بيتصمم على الحمل المحوري بس، والانبعاج مهمل، وحديده على الأقل 0.8%."}},{t:"eq",tex:["M_B = V\\,L_c + \\dfrac{w\\,L_c^2}{2},\\qquad M_A = M_B + X\\,S\\,H","P_u = 0.35\\,A_c\\,f_{cu} + 0.67\\,A_s\\,f_y,\\qquad A_s \\ge 0.008\\,A_c"],caption:{en:"First line: the column of a cantilever frame whose tip carries V and is pulled outwards by X·S at the height H; second line: the strut from the tip to the next column, an axially loaded short member.",ar:"السطر الأول: عمود إطار كابولي طرفه شايل V ومشدود لبره بـ X·S على ارتفاع H؛ والسطر التاني: الدعامة من الطرف للعمود اللي بعده، عضو قصير محمّل محورياً."}},{t:"p",text:{en:"**Example.** Column 6.0 m, arm $L_c = 2.5$ m weighing 10 kN/m, tip load $V = 180$ kN and pull $X\\,S = 120$ kN: $M_B = 180\\times2.5 + 10\\times2.5^2/2 = 481.3$ kN·m and $M_A = 481.3 + 120\\times6.0 = 1201.3$ kN·m; with $N = 420$ kN the footing would have to move $1201.3/420 = 2.86$ m. With a 300 × 300 strut the column keeps 481.3 kN·m down to its base, $e = 481.3/420 = 1.15$ m; the concrete alone carries $0.35\\times300^2\\times25 = 787.5$ kN, far more than 120 kN, so the strut takes the minimum $0.008\\times300^2 = 720$ mm² → 4Ø16 (804 mm²).",ar:"**مثال.** عمود 6.0 م، وذراع $L_c = 2.5$ م وزنه 10 kN/m، وحمل الطرف $V = 180$ kN والشدّة $X\\,S = 120$ kN: $M_B = 180\\times2.5 + 10\\times2.5^2/2 = 481.3$ kN·m و $M_A = 481.3 + 120\\times6.0 = 1201.3$ kN·m؛ ومع $N = 420$ kN القاعدة كانت هتحتاج تترحّل $1201.3/420 = 2.86$ م. وبدعامة 300 × 300 العمود بيفضل عليه 481.3 kN·m لحد قاعدته، و $e = 481.3/420 = 1.15$ م؛ والخرسانة لوحدها بتشيل $0.35\\times300^2\\times25 = 787.5$ kN، أكتر بكتير من 120 kN، فالدعامة بتاخد الحد الأدنى $0.008\\times300^2 = 720$ مم² ← 4Ø16 (804 مم²)."}},{t:"p",text:{en:"**The arm itself** carries its moment together with the pull $T = X\\,S$: a section in **tension and bending**. When $e = M/T$ is more than half the depth, the force is moved to the tension steel as for a column, but with the opposite signs: $e_s = e - t/2 + c$, $M_s = T\\,e_s$, a beam design for $M_s$ — and the tension is **added** to the steel. (With a smaller $e$ the whole section is in tension and $T$ is shared between the two layers of steel.) **Without the strut** the second column is a cantilever as well: its head takes the post reactions $R_{VL}$ down and $R_{HL}$ sideways, its base the moment $R_{HL}\\,h$, and its footing is shifted too.",ar:"**الذراع نفسه** شايل عزمه مع الشدّة $T = X\\,S$: قطاع عليه **شد وعزم**. لما $e = M/T$ تبقى أكبر من نص العمق، القوة بتتنقل لحديد الشد زي العمود بالظبط، بس بالإشارات العكسية: $e_s = e - t/2 + c$، و $M_s = T\\,e_s$، وتصميم ككمرة على $M_s$ — والشد **بيتزوّد** على الحديد. (ولو $e$ أصغر من كده القطاع كله بيبقى شد و $T$ بتتقسم على طبقتين الحديد.) و**من غير الدعامة** العمود التاني بيبقى كابولي هو كمان: راسه بتاخد ردود أفعال القوائم $R_{VL}$ لتحت و $R_{HL}$ لجنب، وقاعدته العزم $R_{HL}\\,h$، وقاعدته بتترحّل هي كمان."}},{t:"eq",tex:["e = \\dfrac{M}{T},\\qquad e_s = e - \\dfrac{t}{2} + c,\\qquad M_s = T\\,e_s","A_s = \\dfrac{M_s}{J\\,f_y\\,d} + \\dfrac{T}{f_y/\\gamma_s},\\qquad M_F = R_{HL}\\,h"],caption:{en:"A member in tension and bending with e/t > 0.5 (c = distance from the face to the centre of the tension steel); M_F = base moment of the post column without a strut, h = its height.",ar:"عضو عليه شد وعزم و e/t > 0.5 (c = المسافة من الوش لمركز حديد الشد)؛ و M_F = عزم قاعدة عمود القوائم من غير دعامة، و h = ارتفاعه."}},{t:"p",text:{en:"**Example.** The arm of the example above, 400 × 800 ($d = 750$ mm, $c = 50$ mm, $f_{cu} = 25$, $f_y = 400$ N/mm²), at its root: $M = 481.3$ kN·m with $T = 120$ kN. $e = 481.3/120 = 4.01$ m, $e/t = 5.0 > 0.5$; $e_s = 4.01 - 0.40 + 0.05 = 3.66$ m and $M_s = 120\\times3.66 = 439.2$ kN·m; $C_1 = 750/\\sqrt{439.2\\times10^6/(25\\times400)} = 3.58$ → $J = 0.785$; $A_s = 439.2\\times10^6/(0.785\\times400\\times750) + 120\\times10^3/(400/1.15) = 1865 + 345 = 2210$ mm² (above $\\mu_{min}\\,b\\,d = 844$ mm²) → 6Ø22 (2281 mm²), all in one row: $(400 - 25)/(22 + 25) = 7.98$ → 7. Its compression face, as in every frame member, takes hangers $0.4\\,A_s = 884$ mm² → 3Ø20 (942 mm²). Without the strut the post column, also 6.0 m high and pushed by the same 120 kN, would take $120\\times6.0 = 720$ kN·m at its base.",ar:"**مثال.** ذراع المثال اللي فوق، 400 × 800 ($d = 750$ مم، و $c = 50$ مم، و $f_{cu} = 25$، و $f_y = 400$ N/mm²)، عند جذره: $M = 481.3$ kN·m مع $T = 120$ kN. $e = 481.3/120 = 4.01$ م، و $e/t = 5.0 > 0.5$؛ و $e_s = 4.01 - 0.40 + 0.05 = 3.66$ م و $M_s = 120\\times3.66 = 439.2$ kN·m؛ و $C_1 = 750/\\sqrt{439.2\\times10^6/(25\\times400)} = 3.58$ ← $J = 0.785$؛ و $A_s = 439.2\\times10^6/(0.785\\times400\\times750) + 120\\times10^3/(400/1.15) = 1865 + 345 = 2210$ مم² (أكبر من $\\mu_{min}\\,b\\,d = 844$ مم²) ← 6Ø22 (2281 مم²)، كلهم في صف واحد: $(400 - 25)/(22 + 25) = 7.98$ ← 7. ووش الضغط بتاعه، زي أي عنصر في إطار، بياخد كانات تعليق $0.4\\,A_s = 884$ مم² ← 3Ø20 (942 مم²). ومن غير الدعامة عمود القوائم، وارتفاعه برضه 6.0 م ومزقوق بنفس الـ 120 kN، كان هياخد $120\\times6.0 = 720$ kN·m عند قاعدته."}},{t:"p",text:{en:"**The cantilever column itself, without the strut.** At its base the column of the example takes $M_A = 1201.3$ kN·m with $N = 420$ kN. As a 400 × 800 section ($d = 750$ mm): $420\\times10^3/(25\\times400\\times800) = 0.053 > 0.04$, so $N$ stays in; $e = 1201.3/420 = 2.86$ m, $e/t = 3.58$, $e_s = 2.86 + 0.40 - 0.05 = 3.21$ m, $M_s = 420\\times3.21 = 1348.2$ kN·m and $C_1 = 750/\\sqrt{1348.2\\times10^6/(25\\times400)} = 750/367.2 = 2.04$ — below $C_{1,min} = 2.83$ for $f_y = 400$ (2.78 for $f_y = 360$): the section is **over-reinforced**. Make it **deeper** first, before reaching for compression steel: $d_{min} = 2.83\\times367.2 = 1039$ → $d = 1050$, $t = 1150$ mm. Check $N$ again: $420\\times10^3/(25\\times400\\times1150) = 0.037 < 0.04$ — design for $M$ alone: $C_1 = 1050/\\sqrt{1201.3\\times10^6/(25\\times400)} = 3.03$ → $J = 0.746$, $A_s = 1201.3\\times10^6/(0.746\\times400\\times1050) = 3834$ mm² → 8Ø25 (3927 mm², two rows), with $0.4\\,A_s = 1534$ mm² as hangers on the compression face → 4Ø25. With the strut the same column carries only 481.3 kN·m.",ar:"**العمود الكابولي نفسه، من غير الدعامة.** عند قاعدته عمود المثال بياخد $M_A = 1201.3$ kN·m مع $N = 420$ kN. كقطاع 400 × 800 ($d = 750$ مم): $420\\times10^3/(25\\times400\\times800) = 0.053 > 0.04$، يبقى $N$ مايتهملش؛ و $e = 1201.3/420 = 2.86$ م، و $e/t = 3.58$، و $e_s = 2.86 + 0.40 - 0.05 = 3.21$ م، و $M_s = 420\\times3.21 = 1348.2$ kN·m، و $C_1 = 750/\\sqrt{1348.2\\times10^6/(25\\times400)} = 750/367.2 = 2.04$ — أقل من $C_{1,min} = 2.83$ لـ $f_y = 400$ (و 2.78 لـ $f_y = 360$): القطاع **زائد التسليح**. **عمّقه** الأول، قبل ما تلجأ لحديد ضغط: $d_{min} = 2.83\\times367.2 = 1039$ ← $d = 1050$، و $t = 1150$ مم. وراجع $N$ تاني: $420\\times10^3/(25\\times400\\times1150) = 0.037 < 0.04$ — صمّم على $M$ لوحده: $C_1 = 1050/\\sqrt{1201.3\\times10^6/(25\\times400)} = 3.03$ ← $J = 0.746$، و $A_s = 1201.3\\times10^6/(0.746\\times400\\times1050) = 3834$ مم² ← 8Ø25 (3927 مم²، على صفين)، مع $0.4\\,A_s = 1534$ مم² حديد تعليق على وش الضغط ← 4Ø25. وبالدعامة نفس العمود مش شايل غير 481.3 kN·m."}},{t:"quiz",q:{kind:"num",q:{en:"A 1.5 m cantilever slab carries w_s = 10 kN/m²; frames every 5 m. Moment handed to each column by the edge beam (kN·m)?",ar:"بلاطة كابولي 1.5 م شايلة w_s = 10 kN/m²؛ والإطارات كل 5 م. العزم اللي الكمرة الطرفية بتسلّمه لكل عمود (kN·m)؟"},answer:56.25,tol:.005,unit:"kN·m",explain:{en:"$M_c = 10\\times1.5^2/2\\times5 = 56.25$ kN·m (1.5 ≤ 2.0 m: a cantilever slab is enough).",ar:"$M_c = 10\\times1.5^2/2\\times5 = 56.25$ kN·m (1.5 ≤ 2.0 م: بلاطة كابولي كفاية)."}}}]},{id:"headroom",title:{en:"More clear height with knee haunches",ar:"ارتفاع صافي أكبر بفيونكات الأركان"},blocks:[{t:"p",text:{en:"When a hall needs more clear height under its frames, **haunch the knees**: a deeper beam end (and column top) is stiffer, attracts more of the negative moment, and leaves less positive moment at mid-span — so the beam can be shallower over the middle of the hall, where the headroom counts. The haunches lower the ceiling only next to the columns.",ar:"لما الصالة تحتاج ارتفاع صافي أكبر تحت إطاراتها، **اعمل فيونكات للأركان**: طرف الكمرة (وراس العمود) الأعمق أجسأ، بيسحب أكتر من العزم السالب، وبيسيب عزم موجب أقل في نص البحر — فالكمرة تقدر تبقى أوطى فوق نص الصالة، مكان ما الارتفاع الصافي بيفرق. والفيونكات بتوطّي السقف جنب الأعمدة بس."}},{t:"p",text:{en:"It is the trick of haunched bridge girders. At the kink where the haunch meets the beam soffit the bottom face turns inwards — a re-entrant corner: let the bottom bars **cross** there (scissors), each anchored past the kink; a bar bent round it would push the cover off.",ar:"دي نفس فكرة كمرات الكباري اللي بفيونكات. وعند الكسرة اللي الفيونكة بتقابل فيها بطن الكمرة، الوش السفلي بيلف لجوه — ركن داخلي: خلّي الأسياخ السفلية **تتقاطع** هناك (مقص)، وكل سيخ متثبت بعد الكسرة؛ السيخ المتني حواليها هيقلع الغطاء."}},{t:"p",text:{en:"**Example.** Two-hinged frame, $L = 18$ m, $H = 6$ m, $w = 60$ kN/m, beam 400 × 1200 ($wL^2/8 = 2430$ kN·m). Plain knees: $M_{knee} = 1321.8$, $M_{mid} = 1108.2$ kN·m → $d = 3.5\\sqrt{M/(f_{cu}b)}$ needs 1.30 m at mid-span. Knees 2.16 m deep ($1.8t$) haunched over 3.6 m, columns as deep: $M_{knee} = 1799.4$, $M_{mid} = 630.6$ kN·m → 1.00 m. **0.30 m** of headroom gained over the whole middle of the hall.",ar:"**مثال.** إطار ذو مفصلين، $L = 18$ م، و $H = 6$ م، و $w = 60$ kN/m، وكمرة 400 × 1200 ($wL^2/8 = 2430$ kN·m). أركان عادية: $M_{knee} = 1321.8$، و $M_{mid} = 1108.2$ kN·m ← $d = 3.5\\sqrt{M/(f_{cu}b)}$ محتاج 1.30 م في نص البحر. وأركان عمقها 2.16 م ($1.8t$) بفيونكة على 3.6 م، والأعمدة بنفس العمق: $M_{knee} = 1799.4$، و $M_{mid} = 630.6$ kN·m ← 1.00 م. **0.30 م** ارتفاع صافي مكسوب على نص الصالة كله."}},{t:"lab",lab:"frame",height:470,props:{template:"haunchframe",params:{haunch:"none"},lockTemplate:!0,missions:$},caption:{en:"A hall frame with plain or haunched knees; the Hand method compares both and gives the mid-span depth.",ar:"إطار صالة بأركان عادية أو بفيونكات؛ والحل اليدوي بيقارن الاتنين وبيدّي عمق نص البحر."}},{t:"quiz",q:{kind:"num",q:{en:"In the example, how much clear height do the haunches gain at mid-span (m)?",ar:"في المثال، الفيونكات بتكسب قد إيه ارتفاع صافي في نص البحر (م)؟"},answer:.3,tol:.003,unit:"m",explain:{en:"$1.30 - 1.00 = 0.30$ m.",ar:"$1.30 - 1.00 = 0.30$ م."}}}]},{id:"problems",title:{en:"Exam-style problems",ar:"مسائل على طريقة الامتحان"},blocks:[{t:"steps",items:[{en:"**A 24 × 60 m workshop that needs north light**, medium soil: saw-tooth slabs (4–8 m) on frames across the 24 m every 6 m; 24 m is past the two-hinged range, so fixed-base frames; the glazing faces north.",ar:"**ورشة 24 × 60 م محتاجة إضاءة شمالية**، تربة متوسطة: بلاطات منشارية (4–8 م) على إطارات عبر الـ 24 م كل 6 م؛ و 24 م بعد مدى الإطار ذو المفصلين، فإطارات ثابتة الركائز؛ والإزاز ناحية الشمال."},{en:"**Two bays of 9 m and 20 m side by side, both lit from the north**: saw-tooth slabs over both; a simple girder ($9/10 = 0.9$ m deep) under the narrow bay and a two-hinged frame under the wide one, solved by moment distribution; the girder's column carries its load plus the additional moment of buckling.",ar:"**باكيتين 9 م و 20 م جنب بعض، والاتنين إضاءتهم شمالية**: بلاطات منشارية فوق الاتنين؛ وكمرة بسيطة (عمقها $9/10 = 0.9$ م) تحت الباكية الضيقة وإطار ذو مفصلين تحت العريضة، بيتحل بتوزيع العزوم؛ وعمود الكمرة بيشيل حمله زائد العزم الإضافي للانبعاج."},{en:"**A round exhibition hall of Ø 26 m** with a sky-light of radius 2 m: radial frames, $L = 11$ m; $2\\pi\\times13/8 = 10.2$ → 12 frames, 6.8 m apart; $t = 11/8 \\to 11/6 = 1.38 \\to 1.83$ m; an inner compression ring; the outer ring on 12 columns is a continuous beam. If the roof may curve, a dome on a ring beam over the columns is the other answer.",ar:"**صالة معارض دائرية Ø 26 م** بشخشيخة نص قطرها 2 م: إطارات شعاعية، $L = 11$ م؛ و $2\\pi\\times13/8 = 10.2$ ← 12 إطار، بينهم 6.8 م؛ و $t = 11/8 \\to 11/6 = 1.38 \\to 1.83$ م؛ وحلقة داخلية مضغوطة؛ والحلقة الخارجية على 12 عمود كمرة مستمرة. ولو السقف ممكن يتقوّس، قبة على كمرة حلقية فوق الأعمدة هي الإجابة التانية."},{en:"**A 36 × 60 m sports hall**, no columns inside: an RC truss ($h = 36/8 \\to 36/6 = 4.5 \\to 6.0$ m) for a flat roof, or an arch girder (rise 4.5–6.0 m) for a curved one; both are roller–hinged, so the columns take vertical loads and wind only.",ar:"**صالة رياضية 36 × 60 م**، من غير أعمدة جوه: جمالون خرساني ($h = 36/8 \\to 36/6 = 4.5 \\to 6.0$ م) لسقف أفقي، أو كمرة مقوّسة (ارتفاع 4.5–6.0 م) لسقف منحني؛ والاتنين مفصلي–متحرك، فالأعمدة بتاخد أحمال رأسية ورياح بس."},{en:"**A banking hall of 18 m under three office floors**: 18 m ≤ 24 m, so a fixed transfer frame on each column line is enough — 600–800 mm wide, $t \\approx 18/8 \\to 18/7 = 2.25 \\to 2.57$ m. Where the first office storey must itself stay open as rooms and corridors, a storey-deep Vierendeel (members $18/12 \\to 18/10$ = 1.5–1.8 m, 600 wide) does it.",ar:"**صالة بنك 18 م تحت تلات أدوار مكاتب**: 18 م ≤ 24 م، يبقى إطار تحويل ثابت على كل خط أعمدة كفاية — عرضه 600–800 مم، و $t \\approx 18/8 \\to 18/7 = 2.25 \\to 2.57$ م. ولو أول دور مكاتب نفسه لازم يفضل مفتوح أوض وممرات، فيرندل بعمق دور (الأعضاء $18/12 \\to 18/10$ = 1.5–1.8 م، وعرض 600) بيعمل كده."},{en:"**A hall on soft clay, 16 m span, with a 7 m level difference between its two parts**: three-hinged frames, and a settlement joint between the parts.",ar:"**صالة على طين ضعيف، بحر 16 م، وفرق منسوب 7 م بين جزئيها**: إطارات ثلاثية المفصلات، وفاصل هبوط بين الجزئين."},{en:"**An L-shaped hall with no interior column allowed**: a structural joint along the short line into two rectangles, and a heavy frame along that joint line carrying the ends of the frames that meet it.",ar:"**صالة على شكل L وممنوع أي عمود داخلي**: فاصل إنشائي على الخط القصير لمستطيلين، وإطار حامل على طول خط الفاصل ده شايل أطراف الإطارات اللي بتقابله."},{en:"**A grandstand roof reaching 7 m**: a 6 m cantilever frame plus a 1.5 m cantilever slab; beyond 7.5 m add a tie or a strut.",ar:"**سقف مدرج طالع 7 م**: إطار كابولي 6 م زائد بلاطة كابولي 1.5 م؛ وبعد 7.5 م ضيف شداد أو دعامة."}]},{t:"p",text:{en:"**More layouts.**",ar:"**تصميمات تانية.**"}},{t:"steps",items:[{en:"**A 75 × 75 m hall on weak soil, columns only every 25 m both ways**: expansion joints along every 25 m line in both directions — nine 25 × 25 m blocks, twin beams and columns at the joints. Simple girders of 25 m every 5 m on a real hinge and a real roller, $t = L/10 = 2.5$ m, resting on **Y-shaped column heads** — two short cantilevers, one girder end on each, 20 mm apart. Or girders of 25 m with 5 m cantilevers carrying a 15 m floating bay ($25 + 5 + 15 + 5 + 25 = 75$): $t = \\max(25/12,\\ 5/5) = 2.08$ → 2.1 m — a weak-soil illustration, since a cantilevered system past 24 m is normally a truss. Better: tied arch girders of 25 m every 5 m, rise $25/8 \\to 25/6 = 3.1 \\to 4.2$ → 3.5 m, on bearing pads on the Y-heads, with the arch, tie and column axes meeting over the bearing.",ar:"**صالة 75 × 75 م على تربة ضعيفة، والأعمدة كل 25 م في الاتجاهين بس**: فواصل تمدد على كل خط 25 م في الاتجاهين — تسع بلوكات 25 × 25 م، وكمرات وأعمدة توأم عند الفواصل. كمرات بسيطة 25 م كل 5 م على مفصلة حقيقية وركيزة متحركة حقيقية، و $t = L/10 = 2.5$ م، قاعدة على **رؤوس أعمدة على شكل Y** — كابولين قصيرين، على كل واحد طرف كمرة، وبينهم 20 مم. أو كمرات 25 م بكوابيل 5 م شايلة باكية عائمة 15 م ($25 + 5 + 15 + 5 + 25 = 75$): $t = \\max(25/12,\\ 5/5) = 2.08$ ← 2.1 م — مثال للتربة الضعيفة بس، لأن النظام اللي بكابولي بعد 24 م عادة بيبقى جمالون. والأحسن: كمرات مقوّسة بشدادات 25 م كل 5 م، ارتفاعها $25/8 \\to 25/6 = 3.1 \\to 4.2$ ← 3.5 م، على ألواح ارتكاز فوق رؤوس الـ Y، ومحاور العقد والشداد والعمود بتتقابل فوق الارتكاز."},{en:"**A bridge between two buildings** must be determinate — hinge and roller — so that differential settlement cannot break it. A link of about 20 m: a simple girder as a floating bay, its dapped ends on short cantilevers of the buildings (check the shear of the reduced nib). About 30 m: a tied arch girder as the floating bay, its rise limited by the storey — a 28 m link under a 3.0 m storey has $L/9.3$ — with the walking slab at tie level and a cover slab at the top chord (or the walking slab only).",ar:"**كوبري بين مبنيين** لازم يبقى محدد — ركيزة مفصلية ومتحركة — علشان الهبوط النسبي مايكسرهوش. وصلة حوالي 20 م: كمرة بسيطة كباكية عائمة، أطرافها المتدرّجة (Dapped ends) قاعدة على كوابيل قصيرة طالعة من المبنيين (راجع القص في الكتف المقصوص). وحوالي 30 م: كمرة مقوّسة بشداد كباكية عائمة، ارتفاعها محدود بالدور — وصلة 28 م تحت دور 3.0 م ليها $L/9.3$ — وبلاطة المشي على منسوب الشداد وبلاطة تغطية عند الوتر العلوي (أو بلاطة المشي بس)."},{en:"**A 24 × 24 m roof on eight columns** (corners and mid-sides): a 24 m frame between two opposite mid-side columns, continuous edge girders of 12 + 12 m on the other two sides, and secondary beams of 12 m from the edge girders to the frame every 3 m. Or four frames joining the mid-side columns along the diagonals — a diamond of spans $12\\sqrt2 = 16.97$ m — with panelled (crossing) beams inside it and hollow-block slabs in the four corner triangles on the edge girders.",ar:"**سقف 24 × 24 م على تمن أعمدة** (الأركان ونصوص الأضلاع): إطار 24 م بين عمودين متقابلين في نص الضلع، وكمرات طرفية مستمرة 12 + 12 م على الضلعين التانيين، وكمرات متشالة 12 م من الكمرات الطرفية للإطار كل 3 م. أو أربع إطارات بتربط أعمدة نصوص الأضلاع على الأقطار — معيّن بحوره $12\\sqrt2 = 16.97$ م — وجواه كمرات متقاطعة (Paneled beams)، وبلاطات هوردي في المثلثات الأربعة اللي في الأركان على الكمرات الطرفية."},{en:"**A side-lit hall beside a saw-tooth hall**: build a wall between them, so that the direct light of the one does not spoil the even north light of the other.",ar:"**صالة إضاءتها جانبية جنب صالة منشارية**: ابني حائط بينهم، علشان الإضاءة المباشرة في واحدة ماتبوّظش الإضاءة الشمالية المنتظمة في التانية."},{en:"**A building over a column-free hall, or floors hung from roof trusses on two central columns**: the transfer frame and the hung floors are in the Vierendeel episode.",ar:"**مبنى فوق صالة من غير أعمدة، أو أدوار متعلقة من جمالونات السقف على عمودين في النص**: إطار التحويل والأدوار المتعلقة في حلقة الفيرندل."},{en:"**A saw-tooth hall of 20 × 35 m on a 5 × 7 m grid** (axes A–E every 5 m across the teeth, rows every 7 m), glazing to the north — the columns that may stay decide the system. **All of them**: slab type on columns, 5 m teeth, Y-beams spanning the 7 m between the columns, $t = 7/12 + 0.15 = 0.73$ → 0.75 m. **Axes B and D left out**: either a girder type of 10 m, $t = 10/(12 \\to 14) = 0.83 \\to 0.71$ m, or the 5 m slab-type teeth kept and their Y-beams on B and D carried by a girder continuous over A, C and E (10 + 10 m, $t = 10/12 = 0.83$ → 0.85 m). **B, C and D left out**: 20 m clear — slab-type teeth on two-hinged frames every 7 m, $t = 20/(12 \\to 14) = 1.67 \\to 1.43$ → 1.5 m; the ridges are perpendicular to the frames, so the glazing may lean.",ar:"**صالة منشارية 20 × 35 م على شبكة 5 × 7 م** (المحاور A–E كل 5 م عمودي على السنّات، والصفوف كل 7 م)، والإزاز ناحية الشمال — الأعمدة اللي مسموح تفضل هي اللي بتحدد النظام. **كلها موجودة**: نوع البلاطة على أعمدة، سنّات 5 م، وكمرات Y بحرها الـ 7 م اللي بين الأعمدة، $t = 7/12 + 0.15 = 0.73$ ← 0.75 م. **المحورين B و D من غير أعمدة**: يا إما نوع الكمرة بحر 10 م، $t = 10/(12 \\to 14) = 0.83 \\to 0.71$ م، يا إما نسيب سنّات نوع البلاطة الـ 5 م وكمرات Y بتاعتها على B و D تشيلها كمرة مستمرة على A و C و E (10 + 10 م، $t = 10/12 = 0.83$ ← 0.85 م). **B و C و D من غير أعمدة**: 20 م حرة — سنّات نوع البلاطة على إطارات ذات مفصلين كل 7 م، $t = 20/(12 \\to 14) = 1.67 \\to 1.43$ ← 1.5 م؛ وخطوط التاج عمودية على الإطارات، فالإزاز ممكن يميل."},{en:"**An L-shaped saw-tooth hall on a 4.5 × 9 m grid**, glazing to the north in both wings. In the wing whose 4.5 m bays run north–south the teeth are 4.5 m: slab type on columns, Y-beams of 9 m, $t = 9/12 + 0.15 = 0.90$ m. In the other wing the 9 m bays run north–south, so every tooth is 9 m long: a girder type, $t = 9/(12 \\to 14) = 0.75 \\to 0.64$ m. One plan, one north, two systems — and a structural joint, which is also the expansion joint, between the wings.",ar:"**صالة منشارية على شكل L على شبكة 4.5 × 9 م**، والإزاز ناحية الشمال في الجناحين. في الجناح اللي بواكيه الـ 4.5 م ماشية شمال–جنوب السنّات 4.5 م: نوع البلاطة على أعمدة، وكمرات Y بحر 9 م، $t = 9/12 + 0.15 = 0.90$ م. وفي الجناح التاني البواكي الـ 9 م هي اللي ماشية شمال–جنوب، فكل سنّة طولها 9 م: نوع الكمرة، $t = 9/(12 \\to 14) = 0.75 \\to 0.64$ م. مسقط واحد وشمال واحد ونظامين — وفاصل إنشائي بين الجناحين، هو نفسه فاصل التمدد."},{en:"**A bus shed or a loading canopy on four corner columns**: the two frames stand on the long sides and the secondary beams span the short way between them as simple beams (the indeterminate-frames episode gives their loads).",ar:"**مظلة أتوبيسات أو رصيف تحميل على أربع أعمدة في الأركان**: الإطارين بيقفوا على الضلعين الطوال والكمرات المتشالة بحرها في الاتجاه القصير بينهم ككمرات بسيطة (حلقة الإطارات غير المحددة بتدّي أحمالها)."}]},{t:"quiz",q:{kind:"mcq",q:{en:"A 20 m hall on weak soil must stay column-free. The first choice is…",ar:"صالة 20 م على تربة ضعيفة لازم تفضل من غير أعمدة. أول اختيار…"},options:[{en:"a tied polygon frame on a hinge and a roller",ar:"إطار مضلع بشداد على ركيزة مفصلية ومتحركة"},{en:"a fixed-base frame",ar:"إطار ثابت الركائز"},{en:"a continuous girder",ar:"كمرة مستمرة"}],answer:0,explain:{en:"Weak soil wants an externally determinate system. A three-hinged frame stops at about 16 m; from 16 to 24 m the choice is the tied polygon frame, which brings no thrust and no moment to its footings.",ar:"التربة الضعيفة عايزة نظام محدد خارجياً. والإطار ثلاثي المفصلات بيقف عند حوالي 16 م؛ ومن 16 لـ 24 م الاختيار هو الإطار المضلع بشداد، اللي مابيجيبش دفع ولا عزم لقواعده."}}}]},{id:"apply",title:{en:"Your building: a system for every part of the site",ar:"مبناك: نظام لكل جزء في الموقع"},blocks:[{t:"p",text:{en:"Put the workshop options of these episodes side by side — concrete of the roof structure per 6 m bay: the **two-hinged frame** of the systems introduction 14.7 m³ (flat roof, 917.3 kN·m at mid-span), the **tied arch slab** 11.4 m³ (M ≈ 0, ties every 6 m), the **RC truss** 14.3 m³ and the **Vierendeel** 19.6 m³ — the last two below their usual 15–40 m.",ar:"حط بدائل الورشة بتاعة الحلقات دي جنب بعض — خرسانة هيكل السقف لكل باكية 6 م: **الإطار ذو المفصلين** بتاع مقدمة الأنظمة 14.7 م³ (سقف أفقي، و 917.3 kN·m في النص)، و**البلاطة المقوّسة بشدادات** 11.4 م³ (M ≈ 0، وشدادات كل 6 م)، و**الجمالون الخرساني** 14.3 م³، و**الفيرندل** 19.6 م³ — والاتنين الأخرانيين أقل من مداهم المعتاد 15–40 م."}},{t:"steps",items:[{en:"**Workshop**: the two-hinged frame stays — flat roof, simple formwork, no ties across the hall. The arch slab saves 3.2 m³ (22%) per bay and would win on a longer hall where its curved formwork is reused.",ar:"**الورشة**: الإطار ذو المفصلين بيفضل — سقف أفقي وشدة بسيطة ومن غير شدادات عبر الصالة. والبلاطة المقوّسة بتوفّر 3.2 م³ (22%) في الباكية وكانت هتكسب في صالة أطول تتكرر فيها شدتها المنحنية."},{en:"**RC block**: spans of 4–5 m need no large-span system — slabs on beams, and the grid for the missing column B2.",ar:"**المبنى الخرساني**: بحور 4–5 م مش محتاجة نظام بحور كبيرة — بلاطات على كمرات، والجريد للعمود B2 اللي اتشال."},{en:"**Link to the workshop**: a simple girder on short cantilevers — determinate, free to move with both buildings.",ar:"**الممر للورشة**: كمرة بسيطة على كوابيل قصيرة — محددة، وحرة تتحرك مع المبنيين."},{en:"**Water tower**: a dome on a ring beam over the tank, and the tank on a ring beam over six columns.",ar:"**برج المية**: قبة على كمرة حلقية فوق الخزان، والخزان على كمرة حلقية فوق ست أعمدة."}]},{t:"widget",w:"building",props:{focus:"WT-1",tags:["footings","cols-g","beams-1","slab-1","cols-1","beams-2","slab-2","ws-columns","ws-trusses","tower-dome","sys-indet","sys-studio"]}},{t:"quiz",q:{kind:"num",q:{en:"Concrete saved per 6 m bay by the arch slab instead of the two-hinged frame (m³)?",ar:"الخرسانة اللي البلاطة المقوّسة بتوفّرها لكل باكية 6 م بدل الإطار ذو المفصلين (م³)؟"},answer:3.23,tol:.01,unit:"m³",explain:{en:"$14.66 - 11.43 = 3.23$ m³, 22% of the frame roof.",ar:"$14.66 - 11.43 = 3.23$ م³، يعني 22% من سقف الإطار."}}}]}],quiz:[{kind:"mcq",q:{en:"A 30 m column-free hall on weak soil. Which system suits it?",ar:"صالة 30 م من غير أعمدة على تربة ضعيفة. أنهي نظام يناسبها؟"},options:[{en:"an RC truss on columns (roller–hinged)",ar:"جمالون خرساني على أعمدة (مفصلي–متحرك)"},{en:"a fixed-base frame",ar:"إطار ثابت الركائز"},{en:"a two-hinged frame",ar:"إطار ذو مفصلين"}],answer:0,explain:{en:"In range (15–40 m) and it brings no thrust or moment into the footings.",ar:"في مداه (15–40 م) ومش بيجيب دفع ولا عزم للقواعد."}},{kind:"num",q:{en:"A 5 m post under a system 350 mm wide. Its section side b (m)?",ar:"قائم 5 م تحت نظام عرضه 350 مم. ضلع قطاعه b (م)؟"},answer:.35,tol:.003,unit:"m",explain:{en:"Above 4 m: b × b with b = the width of the system, 8Φ12 — or a hanger.",ar:"فوق 4 م: b × b و b = عرض النظام، و 8Φ12 — أو معلّق."}},{kind:"num",q:{en:"A post carries X = 45 and Y = 60 kN. Its force when it leans along the resultant (kN)?",ar:"قائم شايل X = 45 و Y = 60 kN. قوته لو مايل مع المحصلة (kN)؟"},answer:75,tol:.003,unit:"kN",explain:{en:"$\\sqrt{45^2 + 60^2} = 75$ kN, rise/run $= 60/45$.",ar:"$\\sqrt{45^2 + 60^2} = 75$ kN، والميل $= 60/45$."}},{kind:"num",q:{en:"No ties: X = 20 kN/m, S = 6 m, edge column 5 m. Moment at its base (kN·m)?",ar:"من غير شدادات: X = 20 kN/m، و S = 6 م، والعمود الطرفي 5 م. العزم عند قاعدته (kN·m)؟"},answer:600,tol:.003,unit:"kN·m",explain:{en:"$20\\times6\\times5 = 600$ kN·m.",ar:"$20\\times6\\times5 = 600$ kN·m."}},{kind:"tf",q:{en:"Fixed-base frames are the best choice on weak soil because their moments are the smallest.",ar:"الإطارات ثابتة الركائز أحسن اختيار على التربة الضعيفة لأن عزومها الأصغر."},answer:!1,explain:{en:"They are the most sensitive to settlement; weak soil calls for determinate systems.",ar:"هي الأكتر حساسية للهبوط؛ والتربة الضعيفة عايزة أنظمة محددة."}},{kind:"tf",q:{en:"On weak soil, two parts of a building with a level difference of 7.5 m are separated by a settlement joint.",ar:"على تربة ضعيفة، جزئين من مبنى بينهم فرق منسوب 7.5 م بيتفصلوا بفاصل هبوط."},answer:!0,explain:{en:"Level differences of about 6–8 m on weak soil load the footings very differently.",ar:"فرق المناسيب حوالي 6–8 م على التربة الضعيفة بيحمّل القواعد بشكل مختلف جداً."}},{kind:"num",q:{en:"A round hall with its columns on a circle of radius 14 m. Number of radial frames?",ar:"صالة دائرية أعمدتها على دايرة نص قطرها 14 م. عدد الإطارات الشعاعية؟"},answer:12,tol:.001,explain:{en:"$2\\pi\\times14/8 = 11.0$ → 12 frames.",ar:"$2\\pi\\times14/8 = 11.0$ ← 12 إطار."}},{kind:"num",q:{en:"Arch slab: X = 45 kN/m, ties every 5 m. Tie force (kN)?",ar:"بلاطة مقوّسة: X = 45 kN/m، والشدادات كل 5 م. قوة الشداد (kN)؟"},answer:225,tol:.003,unit:"kN",explain:{en:"$45\\times5 = 225$ kN.",ar:"$45\\times5 = 225$ kN."}}]};export{d as default};
